return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Japanese','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-12 17:53+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ja','plural-forms'=>'nplurals=1; plural=0;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" が保存されました。','"%1$s" created. %2$d template updated.'=>'「%1$s」が作成されました。%2$d テンプレートが更新されました。' . "\0" . '','"%s" created.'=>'「%s」が作成されました。','"product" (replaces "article")'=>'「product」（「article」の代わり）','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"H2をH1と同等とみなす"（設定 → SEO → 分析）：テーマが投稿タイトルをH2内にレンダリングしている場合にこれを有効にします。分析ツールは最初のH2をH1に昇格させるため、スコアが誤ってペナルティを受けるのを防ぎます。','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d文字 — 良好で、理想的な最大値の%2$dをわずかに超えていますが、許容範囲内です。%4$s','%1$d chars — ideal length. %2$s'=>'%1$d 文字 — 理想的な長さです。%2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d文字 — 検索結果ページで切り捨てられる可能性があります（%2$d未満に保つ）。%3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d 文字 — 短すぎます（%2$d～%3$d を目指してください）。%4$s','%1$d chars, %2$d words — good title.'=>'%1$d文字、%2$d語 — 良いタイトルです。','%1$d internal, %2$d external.'=>'%1$d内部リンク、%2$d外部リンク。','%1$d of %2$d image(s) missing alt text.'=>'%1$dの画像のうち、altテキストが欠落しているものが%2$dあります。','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d 投稿が _lf_lang = %2$s にタグ付けされています。' . "\0" . '','%1$d translated, %2$d skipped.'=>'%1$d 件の翻訳、%2$d 件のスキップ。','%1$d words — below recommended minimum of %2$d.'=>'%1$d 語 — 推奨最小値 %2$d 以下です。','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d 語 — 非常に薄いコンテンツです。少なくとも %2$d 語に拡張することをお勧めします。','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%dは既に翻訳済み — <a href="#" class="lf-force-translate">再翻訳を強制</a>','%d external link(s), no internal links.'=>'外部リンク%d個、内部リンクなし。','%d external link(s), no internal links. Add internal links to related content.'=>'%dの外部リンク、内部リンクなし。関連コンテンツへの内部リンクを追加してください。','%d H1 tags found — a page should have exactly one H1.'=>'%d個のH1タグが見つかりました — ページには正確に1つのH1が必要です。','%d image(s), all have alt text.'=>'%d個の画像、すべてにaltテキストがあります。','%d label(s) translated.'=>'%d 個のラベルが翻訳されました。','%d language not yet linked'=>'%d言語はまだリンクされていません' . "\0" . '','%d link updated.'=>'%d 個のリンクが更新されました。' . "\0" . '','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d個のロケールファイルを自動的に削除できませんでした（DISALLOW_FILE_MODSが設定されています）。サーバーまたはWP-CLIを使用して手動で削除してください：wp language core uninstall <locale>' . "\0" . '','%d locale file removed.'=>'%d個のロケールファイルが削除されました。' . "\0" . '','%d locale pack installed.'=>'%d個のロケールパックがインストールされています。' . "\0" . '','%d navigation reference updated.'=>'%d 個のナビゲーション参照が更新されました。' . "\0" . '','%d part reference updated.'=>'%d 個の部分参照が更新されました。' . "\0" . '','%d post'=>'%d 投稿' . "\0" . '','%d rule registered'=>'%d ルールが登録されました' . "\0" . '','%d template repaired.'=>'%d 個のテンプレートが修復されました。' . "\0" . '','%d term(s) translated.'=>'%d 個の用語が翻訳されました。','%d words.'=>'%d語。','%s Archive'=>'%s アーカイブ','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%sはアクティブで、すでにSchema.org JSON-LDを出力しています。Lingua Forgeは、競合するグラフを防ぐために独自のスキーマ出力を無効にしています。Open Graphとは異なり — LFは他のプラグインの出力にog:localeを追加します — スキーマはきれいに補足できません：重複または重なり合うJSON-LDグラフは検証エラーを引き起こします。構造化データをLFに処理させたい場合は、検出されたプラグインのスキーマ出力を無効にしてください。','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%sはアクティブで、独自のサイトマップを生成します。そのサイトマップはLFのものとは別です。両方ともGoogle Search Consoleに送信する必要があります：SEOプラグインのサイトマップはコンテンツをリストし、LFのサイトマップは多言語の代替リンクを追加します。LFのサイトマップは自動的にrobots.txtで告知されます。','(active)'=>'（アクティブ）','(avg %.1f hits/block)'=>'(平均 %.1f ヒット/ブロック)','(avg %.1f hits/entry)'=>'（平均 %.1f ヒット/エントリ）','(classic theme)'=>'（クラシックテーマ）','(disabled)'=>'（無効）','(FSE / block theme)'=>'（FSE / ブロックテーマ）','(no title) #%d'=>'（タイトルなし） #%d','(partial)'=>'（部分的）','(server/FPM timeout still applies)'=>'（サーバー/FPMタイムアウトが引き続き適用されます）','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} は置換可能なリンクがありませんでした — 調査のために再スキャンしてください)','.txt file(s) in the directory'=>'.txtファイルがディレクトリにあります','/ 100'=>'/ 100','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — H2またはH3の小見出しが見つかりません。H2を追加するとstructureが改善されます。','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1つのH1 ✓ — H2のサブ見出しはなし（このコンテンツタイプでは許容される）。','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1つのH1 ✓ — H2はなく、%d個のH3見出しが見つかりました（例：アコーディオン/詳細ヘッダー）。構造は許容範囲です。','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1つのH1 ✓ — 内容は短く（%d段落）、サブ見出しは不要です。','1 H1 ✓, %1$d H2, %2$d H3.'=>'1つのH1 ✓、%1$dのH2、%2$dのH3。','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> &#8220;%2$s&#8221; テーマからのローカライズされたテンプレート %1$d 個はデータベースに保存されていますが、現在は非アクティブです。それらは、そのテーマを再アクティブにすると再び有効になります。新しいテーマに翻訳を引き継ぐには、<strong>設定 → Lingua Forge → ルーター → FSEスキャフォールド</strong>を通じて再生成してください。','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> 自動修正可能なリンク','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> 手動レビューが必要なリンク','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> 古いパス','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> テンプレートの問題','_lf_lang Coverage'=>'_lf_lang カバレッジ','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'サイトのルートに物理的なrobots.txtファイルがあります。WordPressの仮想robots.txt — およびLFのサイトマップ：フィルター — はバイパスされます。LFのサイトマップは検索エンジンに告知されていません。','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'コンパイル済みの.moファイルのみを受け付けます。ファイル名は{textdomain}-{locale}.moのパターンに従う必要があります。同じ名前のファイルをアップロードすると置き換えられます。','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'アクセス禁止 — アカウントが停止されているか、キーに必要な権限がありません。','Action'=>'アクション','active'=>'アクティブ','Active Languages'=>'アクティブな言語','Active languages'=>'アクティブな言語','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'アクティブな言語：サポートしたい各言語を追加してください。各言語にはURLプレフィックスまたはサブドメインと、ページの&lt;head&gt;内にhreflangタグが設定されます。','Active Plugins'=>'アクティブプラグイン','Active preset'=>'アクティブなプリセット','Active Provider'=>'アクティブなプロバイダー','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'アクティブなプロバイダー、設定されたキー、モデルの階層選択、プリセット、日次クォータ。','Active theme'=>'アクティブなテーマ','Active: %s.'=>'アクティブ：%s。','Add entry'=>'エントリを追加','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'ドラフトを改善するための指示を追加します。例：短くする、結論セクションを追加、よりフォーマルな表現を使う、FAQブロックを含める…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'ドラフトを改善するための指示を追加してください — 例：短くする、結論セクションを追加、よりフォーマルな表現を使う…','Add key →'=>'キーを追加 →','Add new entry'=>'新しいエントリを追加','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'1行につき1つの用語を追加します。ソース用語とターゲットのレンダリングの両方が必要です。言語ペアは、制約が適用される翻訳ジョブを決定します。','Add Sitemap directive to robots.txt'=>'robots.txtにSitemapディレクティブを追加','Add the following line to your robots.txt manually:'=>'次の行を手動でrobots.txtに追加してください：','Add WooCommerce product tags to Open Graph output'=>'Open Graph出力にWooCommerceの商品タグを追加','Adds a link to the home page so visitors can browse in their language.'=>'訪問者が自分の言語で閲覧できるようにホームページへのリンクを追加します。','Administrators only (manage_options)'=>'管理者のみ（manage_options）','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'プライマリ言語を変更した後、URLルーティングを更新するためにパーマリンクをフラッシュしてください。','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL構造設定（パスプレフィックス ↔ サブドメイン）を変更した後は、常に設定 → パーマリンクを訪れて、「変更を保存」をクリックして書き換えルールをフラッシュしてください。','AI analysis failed. Please try again.'=>'AI分析に失敗しました。もう一度お試しください。','AI Behaviour Preset'=>'AI動作プリセット','AI cache cleared. %d entry was removed.'=>'AIキャッシュがクリアされました。%d件のエントリが削除されました。' . "\0" . '','AI Configuration'=>'AI設定','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI機能はオプションです。言語ルーティング、hreflang、言語切り替え、翻訳グループシステムは、プロバイダーが設定されていなくても動作します。','AI Limits & Security'=>'AIの制限とセキュリティ','AI Provider'=>'AI プロバイダー','AI provider returned an empty response.'=>'AIプロバイダーが空の応答を返しました。','AI Provider Tab'=>'AIプロバイダタブ','AI Recommendations'=>'AI推奨事項','AI returned an unexpected response format. Please try again.'=>'AIが予期しない応答形式を返しました。もう一度お試しください。','AI translation and batch analysis may time out. Recommend 120s or more.'=>'AI翻訳とバッチ分析はタイムアウトする場合があります。120秒以上を推奨します。','AI Usage'=>'AI使用状況','AI Usage & Cache'=>'AIの使用とキャッシュ','AI Usage & Cache Tab'=>'AI使用量とキャッシュタブ','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120〜160文字を目標にしてください。空白のままにすると抜粋の代替を使用します。','All labels already translated.'=>'すべてのラベルはすでに翻訳済みです。','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Google、Bing、Yandexなどの主要な検索エンジンは、robots.txtのSitemap:ディレクティブを通じて自動的にサイトマップを検出します。手動の操作は必要ありません。下のボタンは即座にpingを送信し、次のrobots.txtのチェックを待たずにサイトマップを再クロールさせます。','All published posts have a _lf_lang value. No gaps detected.'=>'公開済みのすべての投稿には _lf_lang の値があります。ギャップは検出されませんでした。','All template metadata is already up to date.'=>'すべてのテンプレートメタデータは最新の状態です。','All time'=>'全期間','All types'=>'すべてのタイプ','Allow editors to lock individual blocks'=>'編集者が個々のブロックをロックできるようにします','Allow Gutenberg template-editing mode on post screens'=>'投稿画面でGutenbergのテンプレート編集モードを許可します','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'言語割り当て、翻訳関係、メタ記述、用語集、翻訳メモリもアンインストール時に削除します','Also generate meta description'=>'メタ説明も生成する','Alternative (server-side):'=>'代替（サーバー側）：','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'常にog:localeとog:locale:alternateのみを出力します。他のプラグインやテーマが完全なOGセットを処理している場合に使用します。','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'他のプラグインに関係なく、常に完全なOG + Twitter Cardセットを出力します。OGタグを出力しない他のプラグインがない場合のみ使用してください。','An unknown error occurred.'=>'不明なエラーが発生しました。','Analyse'=>'分析','Analyse all languages'=>'すべての言語を分析','Analyse…'=>'分析…','Analysis'=>'分析','Analysis request failed. Please try again.'=>'分析リクエストに失敗しました。もう一度お試しください。','Analyzing…'=>'分析中…','and'=>'および','and set it to one of the active content languages listed above.'=>'上記にリストされたアクティブなコンテンツ言語のいずれかに設定してください。','Anthropic (Claude)'=>'Anthropic（Claude）','Anthropic Console'=>'Anthropicコンソール','any'=>'いずれか','API calls saved by cache'=>'キャッシュされたAPI呼び出し','API Key'=>'APIキー','API Keys'=>'APIキー','API Response Cache'=>'API応答キャッシュ','API Response Cache setting saved.'=>'APIレスポンスキャッシュ設定が保存されました。','Appends the following line to your existing robots.txt: %s'=>'次の行を既存のrobots.txtに追加します：%s','Applied ✓'=>'適用完了 ✓','Apply failed — please try again.'=>'適用に失敗しました — もう一度お試しください。','Apply to all language versions'=>'すべての言語バージョンに適用','Apply to Block'=>'ブロックに適用','Apply to Editor'=>'エディターに適用','Apply to Footnote'=>'脚注に適用','Apply to Meta Description'=>'メタディスクリプションに適用','Apply translation'=>'翻訳を適用','Applying…'=>'適用中…','Approximate size'=>'おおよそのサイズ','Archive'=>'アーカイブ','Archive: %s'=>'アーカイブ：%s','Article / WebPage'=>'記事 / Webページ','Article / WebPage — all singular posts and pages'=>'記事 / Webページ — すべての単一投稿とページ','Attribute label displayed in this language. Leave empty to use the default label.'=>'この言語で表示される属性ラベル。空のままにするとデフォルトのラベルが使用されます。','Authors and above (edit_published_posts)'=>'著者以上（edit_published_posts）','Auto (recommended)'=>'自動（推奨）','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'自動検出割り当て：WooCommerce製品 → 製品プロフィール；静的フロントページ → ランディングプロフィール；その他すべて → ブログプロフィール。この設定を上書きする特定のプロフィールを選択してください。','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'静的フロントページ用に自動検出；手動で選択可能です。タイトル20ポイント · メタディスクリプション30ポイント · 文字数15ポイント · 見出し10ポイント · 画像15ポイント · リンク0ポイント。タイトルのSERP制限は70文字；文字数は150未満で警告、60未満で失敗；H2と内部リンクは任意です。','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'WooCommerce商品用に自動検出。タイトル20ポイント · メタディスクリプション30ポイント · 文字数15ポイント · 見出し5ポイント · 画像20ポイント · リンク0ポイント。タイトルのSERP制限は70文字；文字数は80未満で警告、40未満で失敗；H2と内部リンクは任意です。','Available models reference'=>'利用可能なモデルの参照','avg'=>'平均','Batch Analysis'=>'バッチ分析','Behavior'=>'動作','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'動作：AIプリセット（リテラル、バランス、クリエイティブ）を選択し、サイト全体のカスタムプロンプト指示を追加し、自動投稿保存翻訳を有効または無効にし、翻訳メモリを設定します。','Block Content'=>'ブロックコンテンツ','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'訪問者の言語に翻訳が存在しないため、現在のページがソース言語で表示されている場合に丁寧な通知を表示します。これは、Lingua ForgeルーターのLINGUAFORGE_LANG_FALLBACK_ACTIVE信号によって制御されており、リクエストロケールに翻訳が存在する場合は何も発しません。','Block Editor'=>'ブロックエディター','block keywordfallback'=>'フォールバック','block keywordi18n'=>'i18n','block keywordlanguage'=>'言語','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'翻訳','Block locking'=>'ブロックロック','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'カスタム投稿タイプ用に登録されたブロックパターン。翻訳ボタンを使って言語バリアントを作成します。翻訳された内容はここに保存され、ブロックエディタのパターンインサーターから任意のCPT投稿にコピーしたり、同期パターン（再利用可能ブロック）の出発点として使用できます。','block titleMissing Translation Notice'=>'翻訳なし通知','Block translation reuses'=>'ブロック翻訳の再利用','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'投稿間で共有されるブロックレベルの翻訳キャッシュ。これを有効にすると、同一のブロック（同じマークアップ、言語ペア、用語集）をメモリから提供し、AI呼び出しを省略します。用語集の編集やコンプライアンスプリセットの変更は、自動的に影響を受けるキャッシュ翻訳を無効にします。','Blog / Editorial'=>'ブログ / 編集','Blog / Editorial (default)'=>'ブログ / 編集（デフォルト）','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'ブログ投稿はArticleを使用し、その他の投稿タイプとページはWebPageを使用します。見出し、説明、inLanguage、URL、公開日、更新日、画像、出版社を含みます。','Browser language redirect'=>'ブラウザ言語リダイレクト','Built-in preset instructions:'=>'内蔵プリセット指示:','Bulletize (•-prefixed)'=>'箇条書き（•-プレフィックス）','cached'=>'キャッシュ済み','Cached API responses'=>'キャッシュされたAPI応答','Cached block translations'=>'キャッシュされたブロック翻訳','Cancel'=>'キャンセル','Cannot determine target language from slug.'=>'スラッグからターゲット言語を特定できません。','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'商品ID %1$dの書き込みに失敗しました：これは翻訳されたバージョンです（言語：%2$s）%3$s。操作データ（価格、在庫、SKU、寸法）はソース商品で更新する必要があります。ソース商品IDは次のコマンドで解決してください：GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'カノニカルタグ','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'サイトが生成できるAIの使用量を制限し、有料AI呼び出しをトリガーできるユーザーロールを制限します。既にあるユーザごとのレート制限（30リクエスト/分、ハードコーディング）の上に乗っています。','Cart'=>'カート','chars'=>'文字数','Check your account, billing, or remaining credits directly on the provider console:'=>'プロバイダーコンソールでアカウント、請求、残りクレジットを直接確認：','Checkout'=>'チェックアウト','Chunk translated'=>'翻訳されたチャンク','Chunk translated to:'=>'翻訳されたチャンク：','Clear'=>'クリア','Clear All'=>'すべてクリア','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'すべてのキャッシュされたAI結果をクリアしますか？今後のリクエストはキャッシュの再構築まで新しいAPI呼び出しをトリガーします。','Clear API Response Cache'=>'API応答キャッシュをクリア','Clear Debug Files'=>'デバッグファイルをクリア','Clear hints'=>'ヒントをクリア','Clear input'=>'入力をクリア','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'翻訳メモリ全体をクリアしますか？今後の翻訳はキャッシュを再構築します。','Clear Translation Memory'=>'翻訳メモリをクリア','Close'=>'閉じる','Close language panel'=>'言語パネルを閉じる','Close popover'=>'ポップオーバーを閉じる','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'$wp_rewrite->extra_rules_topにあるLF所有エントリの折りたたみダンプ。新しい言語を追加した後の404エラーやルーティングの競合を診断するのに役立ちます。','Compatibility'=>'互換性','Compliance Preset'=>'コンプライアンスプリセット','Configuration issue: WP site language is not a content language'=>'設定の問題：WPサイトの言語がコンテンツ言語ではありません','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'設定→APIキーでAIプロバイダーを構成し、AIによる推奨を有効にします。','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'サイトのすべての言語に対してhreflang、Open Graph、Schema.org、サイトマップ、ソーシャルシェアを設定します。以下の各セクションは、多言語SEOの一側面を扱います。','Configured'=>'設定済み','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'パーマリンク構造がLingua Forgeのパスルーティングと互換性があることを確認します。プレーンおよび数字のみの構造はサポートされていません。','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Contact Form 7（wpcf7_contact_form）、Flamingoの連絡先と受信メッセージ（flamingo_contact、flamingo_inbound）、およびWordPressの言語パック同期ストレージ（wp_sync_storage）は自動的に除外されます。コンテンツを言語フィルタリングしない他のサードパーティの投稿タイプを、1行またはカンマ区切りで追加してください。','Content generated'=>'コンテンツが生成されました','Content Generator'=>'コンテンツ生成器','Content profiles and weights'=>'コンテンツプロファイルと重み','Content ready'=>'コンテンツ準備完了','Contributors and above — default (edit_posts)'=>'投稿者以上 — デフォルト（edit_posts）','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'AIに送信されるコンテンツの量と応答の大きさを制御します。空白のままにすると、組み込みのデフォルト（プレースホルダーとして表示）を使用します。大きなページが切り捨てられる場合はこれらの値を上げ、小さくしてAPIコストを削減します。','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AIコンテンツジェネレーター機能のトークン予算と入力制限を制御します。空白のままにすると、内蔵のデフォルトが使用されます。','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'管理者がプラグインを削除したときの動作を制御します。プラグイン設定とAIキャッシュは常に削除されます。言語割り当てと翻訳関係はデフォルトで保持されるため、誤ってアンインストールしたり再インストールした場合でも前の状態から再開できます。','Conversational'=>'会話調','Copied ✓'=>'コピー完了 ✓','Copied!'=>'コピー完了！','Copy'=>'コピー','Copy and paste into a GitHub issue or support request.'=>'GitHubの問題やサポートリクエストにコピー＆ペーストしてください。','Copy failed — please copy the URL manually.'=>'コピーに失敗しました — URLを手動でコピーしてください。','Copy markup'=>'マークアップをコピー','Copy system info'=>'システム情報をコピー','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'現在のURLをクリップボードにコピーします。成功すると「リンクがコピーされました」のトーストが表示されます。','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'結果をコピーして必要な場所に貼り付けてください（例：脚注フィールドに直接）。','Copy to safe storage'=>'セーフストレージにコピー','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'copy/native/auto JSアクション：LFのsocial-share.jsによって処理されます','Could not add entry: source term and target term are required.'=>'エントリーを追加できませんでした：ソース用語とターゲット用語は必須です。','Could not copy the file. Check that the uploads folder is writable.'=>'ファイルをコピーできませんでした。アップロードフォルダに書き込み権限があるか確認してください。','Could not instantiate the provider.'=>'プロバイダーをインスタンス化できませんでした。','Could not save the file. Check that the uploads folder is writable.'=>'ファイルを保存できませんでした。アップロードフォルダに書き込み権限があるか確認してください。','Could not save the glossary entry.'=>'用語集のエントリを保存できませんでした。','Could not write to robots.txt. Check file permissions.'=>'robots.txtに書き込めませんでした。ファイルの権限を確認してください。','CPT Block Patterns'=>'CPTブロックパターン','Create'=>'作成','Create missing'=>'不足しているものを作成','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'投稿タイプ "%s" の翻訳を作成するには、アクティブな連携が必要です。必要な連携がインストールされて有効になっていることを確認してください。','Creating…'=>'作成中…','Creative / Marketing'=>'クリエイティブ / マーケティング','Creative / Marketing instructions'=>'クリエイティブ / マーケティング指示','Current content (will be overwritten)'=>'現在の内容（上書きされます）','Current status'=>'現在の状態','Current title'=>'現在のタイトル','Current: {current}'=>'現在: {current}','Currently emitting'=>'現在発信中','Currently inherited from the %s constant. Selecting a value here will override it.'=>'現在、%s定数から継承されています。ここで値を選択すると上書きされます。','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'現在、ブロックコメント属性プレースホルダー（wp:detailsサマリーフィールドなど）を使用する投稿はスキップされ、既存の単一呼び出し翻訳パスにフォールバックします。','Currently:'=>'現在：','Custom'=>'カスタム','Custom tables — LF post-meta filters do not affect orders.'=>'カスタムテーブル — LF投稿メタフィルターは注文には影響しません。','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'日次AIクォータに達しました（%1$dリクエスト）。UTCの%2$sにリセットされます。','Daily quota'=>'日次クォータ','Daily request limit'=>'1日のリクエスト制限','Danger Zone'=>'危険地帯','Debug Files'=>'デバッグファイル','Debug files cleared. %d file was removed.'=>'デバッグファイルがクリアされました。%dファイルが削除されました。' . "\0" . '','Debug Info'=>'デバッグ情報','Debug logging'=>'デバッグログ','Debug logging disabled.'=>'デバッグログ記録は無効です。','Debug logging enabled.'=>'デバッグログが有効になっています。','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'デバッグ：AIプロンプトとAPI応答をローカルファイルに記録するデバッグログを有効にします。トラブルシューティング後は無効にしてください — デバッグモードはすべてのAIリクエストでファイルを書き込みます。','Default OG image'=>'デフォルトOG画像','Default profile'=>'デフォルトプロフィール','Delete'=>'削除','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'デバッグディレクトリ内のすべての.txtファイルを削除しますか？ディレクトリ自体は残るので、今後のデバッグ書き込みは正常に行われます。`define( \'LINGUAFORGE_AI_DEBUG\', true );`をwp-config.phpで設定して、この切り替えを上書きすることもできます。','Delete all files for this override (both .mo and .po)?'=>'この上書きのすべてのファイル（.moと.poの両方）を削除しますか？','Delete content data on uninstall'=>'アンインストール時にコンテンツデータを削除','Delete this glossary entry?'=>'この用語集のエントリを削除しますか？','Describe what to write — topic, key points, structure…'=>'書く内容を説明してください — トピック、重要ポイント、構成…','Destructive action — read before proceeding'=>'破壊的な操作 — 実行前に読んでください','Details ↗'=>'詳細 ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'実行時にアクティブなSEOプラグイン（Yoast、Rank Mathなど）を検出します。別のプラグインがすでに完全なOGセットを出力している場合はog:locale + og:locale:alternateのみを出力します。検出されない場合は完全なセットを出力します。','Directory'=>'ディレクトリ','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'ヘッドレスサイトまたは完全にカスタムされたhreflang実装の場合のみ無効にします。無効にすると、LFはWordPressコアのcanonicalタグを削除しなくなり、SEOプラグインのhreflang出力も抑制しなくなります。','Disabled'=>'無効','Disabled (by setting)'=>'設定による無効','Disabled (mode setting)'=>'モード設定による無効','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'すでにlf-social-share mu-pluginがこの機能を提供しているため無効です。','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODSが設定されています。','Display'=>'表示','Displays the Lingua Forge language switcher.'=>'Lingua Forgeの言語切替器を表示します。','Do not output any OG tags.'=>'OGタグを出力しません。','Documentation'=>'ドキュメント','Done'=>'完了','Done — {done} of {total} post(s) fixed.'=>'完了 — {done} / {total} の投稿を修正しました。','Down'=>'下向き','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'WordPress.orgから直接WordPressコアの言語パックをダウンロードしてインストールします。インストール後、そのロケールはURLルーティングとAI翻訳ワークフローで利用可能になります。利用可能な言語のリストは必要に応じて取得されます — 下のボタンをクリックして読み込みます。','Dropdown direction'=>'ドロップダウンの方向','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'各メトリックは4つの状態のいずれかを示します：ok（完全な重み）、warn（重みの50％）、fail（0）、またはinfo（0、ペナルティなし）。スコア≥80は緑、50–79は琥珀色、50未満は赤です。','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'各投稿はタイトル、メタディスクリプション、文字数、見出し構造、画像のaltカバレッジ、内部リンクの6つのルールベースのメトリックから0〜100のスコアが付けられます。読書時間には常に10ポイントが付与され（情報のみ）、残りの90ポイントは内容プロファイルに応じて異なる重みで他のメトリックに配分されます（詳細は下記）。','edit'=>'編集','Editors and above (edit_others_posts)'=>'編集者以上（edit_others_posts）','Enable API response caching'=>'API応答キャッシュを有効にする','Enable block-level translation cache reuse across posts'=>'投稿間でブロックレベルの翻訳キャッシュの再利用を有効にします','Enable Social Share URL rewriting for Social Icons blocks'=>'ソーシャルアイコンブロックのためのソーシャルシェアURL書き換えを有効にします','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'テーマが投稿タイトルをH1ではなくH2としてレンダリングする場合に有効（いくつかのブロックテーマで一般的）。分析ツールはレンダリングされたページを取得し、H1が見つからずH2が見つかった場合、最初のH2をH1に昇格させてスコアリングします。','Environment'=>'環境','environment variable'=>'環境変数','Error'=>'エラー','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'投稿が分析されるたびにスコアは投稿メタに保存されます。投稿リストの言語列には、少なくとも一度分析された投稿に対して色分けされた「SEO N」バッジが表示されます。2つのスコアが保存されている場合、差分インジケーター（↑N / ↓N）が前回の実行からの変化を示します。','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'正確に1つのH1が必要です。H1は通常、テーマによってレンダリングされる投稿タイトルです — 可能な場合はライブレンダリングページから読み取り、そうでなければ投稿内容から読み取ります。','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'サポートされている設定例：WPサイトの言語＝カタルーニャ語（CA）、コンテンツ言語＝CA + ES。','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'サポートされていない設定例：WPサイトの言語＝英語（EN）、コンテンツ言語＝CA + ESのみ。英語はコンテンツ言語ではないため、Lingua ForgeはWPロケールを翻訳グループにマッピングできません。','Exclude from navigation menus'=>'ナビゲーションメニューから除外','Exclude from routing'=>'ルーティングから除外','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'この投稿タイプを言語ルーティングから除外 — その投稿はここに表示されなくなり、_lf_langも付与されません。自動的に元に戻すことはできません。','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'この投稿タイプを言語ルーティングから除外しますか？その投稿はこのリストに表示されなくなり、_lf_langも付与されません。設定 → ルーター → クエリフィルター除外で逆にできます。','excluded from routing'=>'ルーティングから除外済み','Excluded post types'=>'除外された投稿タイプ','Excluding…'=>'除外中…','Expand'=>'拡張','Expected: {expected}'=>'期待される: {expected}','External share services'=>'外部共有サービス','Extra guidance — tone, style, constraints, target audience…'=>'追加のガイダンス — トーン、スタイル、制約、ターゲット層…','Extra guidance — tone, style, constraints…'=>'追加のガイダンス — トーン、スタイル、制約…','Failed to save exclusion.'=>'除外の保存に失敗しました。','Failed. Please try again.'=>'失敗しました。もう一度お試しください。','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'ページにアイキャッチ画像、サイトロゴ、またはサイトアイコンがない場合に使用されるフォールバック画像URL。アーカイブ、ブログインデックス、サムネイルのない個別ページのソーシャルプレビューに表示されます。','Feature'=>'機能','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'機能は2つの層にグループ化されています。各層とプロバイダーの正確なモデル識別子を入力してください。空白のフィールドはビルトインのデフォルトを使用します（プレースホルダーとして表示）。アクティブなプロバイダーのモデルだけが実行時に呼び出されます。切り替える予定がある場合は事前に設定してください。','File copied to safe storage successfully.'=>'ファイルが安全なストレージに正常にコピーされました。','File modifications are disabled (DISALLOW_FILE_MODS).'=>'ファイルの変更は無効です（DISALLOW_FILE_MODS）。','Files'=>'ファイル','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'ファイルは以下のディレクトリに保存されます。翻訳の問題を診断するのに役立ちます — 必要なものが得られたらオフにして、ファイルが蓄積しないようにしてください。wp-config.phpからも`define( \'LINGUAFORGE_AI_DEBUG\', true );`を使ってこの動作を強制的に設定できます。これは切り替えを上書きします。','Filter'=>'フィルター','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'言語と投稿タイプでフィルタリングし、コンテンツを閲覧し、アイテムをクリックしてルールベースのSEO監査を実行します — タイトルの長さ、メタディスクリプション、語数、見出し構造、画像のaltカバレッジ、内部リンク。','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'linguaforge_debug_dirを使って、デバッグ出力を非公開の場所にリダイレクトします。','Finding'=>'検出中','Fix'=>'修正','Fix All'=>'すべて修正','Fix all links'=>'すべてのリンクを修正','Fix all parts'=>'すべてのパーツを修正','Fix Links'=>'リンクを修正','Fix Nav'=>'ナビゲーションを修正','Fix Parts'=>'パーツを修正','Fix Template'=>'テンプレートを修正','Fix: go to'=>'修正：次に進む','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'これは、データベースに保存されているすべてのLFスキャフォールドされたFSEテンプレートのサイトエディタの名前空間と_lf_langタグを修正します。以前のバージョンのLingua Forgeから更新した後に一度実行してください — これにより、WooCommerce由来のテンプレートがアクティブテーマグループからWooCommerceグループに移動され、すべてのスキャフォールドされたテンプレートがカバレッジレポートで検出可能になります。','Fixing {n} / {total}…'=>'{n} / {total} を修正中…','Fixing…'=>'修正中…','Flush Permalink Rules'=>'パーマリンクルールをフラッシュ','Flush Permalinks'=>'パーマリンクをフラッシュ','Flush Sitemap Cache'=>'サイトマップキャッシュをフラッシュ','Footnote Content'=>'脚注の内容','footnote(s) translated — applied together with content.'=>'脚注が翻訳されました — コンテンツと一緒に適用されました。','Footnotes'=>'脚注','Footnotes payload (advanced)'=>'脚注ペイロード（高度な設定）','Forbidden'=>'禁止されています','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.phpのLINGUAFORGE_AI_DEBUG定数によって強制的にOFFになっています。この行を削除して、ここからこの切り替えを制御してください。','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.phpのLINGUAFORGE_AI_DEBUG定数によって強制的にONになっています。この行を削除して、ここからこの切り替えを制御してください。','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'次のリクエスト時にサイトマップを再生成します。大量インポートや翻訳関係の手動編集後に使用します。','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'バグや予期しない動作を見つけましたか？GitHubでイシューを開いてください — 上記のデバッグ情報ブロックと、期待した動作と実際の動作の簡単な説明を含めてください。','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'<strong>{total}</strong>の中で<strong>{scanned}</strong>の投稿にわたって<strong>{parts}</strong>を見つけました。','From'=>'から','Front Page'=>'フロントページ','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSEローカリゼーション：このタブから直接、フルサイトエディティングのテンプレートやテンプレートパーツのスキャフォールド、翻訳、リンク修正を行います。','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'アクティブテーマからシードされたFSEテンプレート。サイトエディタで作成し、カスタマイズします。','Full'=>'完全','Full Article'=>'全文記事','Full post'=>'全文投稿','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'フルページ翻訳、コンテンツジェネレーター（中Tierモデルは十分です）','General'=>'一般','Generate'=>'生成','Generate Content'=>'コンテンツ生成','Generate content…'=>'コンテンツを生成…','Generate Excerpt'=>'抜粋を生成','Generate Meta Description'=>'メタディスクリプションを生成','Generate the multilingual sitemap at /lf-sitemap.xml'=>'/lf-sitemap.xmlに多言語サイトマップを生成','Generated Content'=>'生成されたコンテンツ','Generated meta description'=>'生成されたメタディスクリプション','Generating…'=>'生成中…','Generation failed.'=>'生成に失敗しました。','Getting started'=>'はじめに','Global AI preset'=>'グローバルAIプリセット','Global default (%s)'=>'グローバルデフォルト (%s)','Glossary'=>'用語集','Glossary entry added.'=>'用語集エントリーが追加されました。','Glossary entry removed.'=>'用語集エントリーが削除されました。','Glossary Tab'=>'用語集タブ','Google (Gemini)'=>'Google（Gemini）','Google AI Studio'=>'Google AIスタジオ','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2をH1として扱うモードが有効 — タイトルはH1とみなされます。（見出しタグはレンダリングされたページから検出できませんでした。テーマがタイトルを正しく出力しているか確認してください。）','Heading structure rules'=>'見出し構造ルール','Headings'=>'見出し','Hide'=>'非表示','High-Performance Order Storage (HPOS)'=>'高性能注文ストレージ（HPOS）','Hints'=>'ヒント','Home link text'=>'ホームリンクのテキスト','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'翻訳に表示されるべき形。AIに対して、内容をそのまま保持するよう指示するために、ソース用語と同じ値を入力してください。','How to use'=>'使い方','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT同期 — 過渡期；LF投稿メタフィルターはCPTのコピーに適用されます。','Hreflang'=>'Hreflang','Hreflang output'=>'Hreflang出力','Hreflang settings saved.'=>'Hreflang設定が保存されました。','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'アイコン + ラベル','Icon only'=>'アイコンのみ','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'チェックすると、プラグインをアンインストールしたときに、すべての言語割り当て、翻訳関係、メタ記述、ページごとのプリセット、AI用語集、翻訳メモリがこのサイトのすべての投稿から恒久的に削除されます。これは元に戻せません。サイトから多言語サポートを完全に削除する場合を除き、チェックを外してください。','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'一般的なSEOプラグインがインストールされている場合、このパネルはLFが重複出力を避けるためにどのように適応しているかを示します。目的は衝突回避 — 協力ではありません。LFは常に多言語SEO層（hreflang、og:locale、inLanguage schema）を提供し、LFの言語ルーティング設定の知識を必要とします。','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Yoast SEO、Rank Math、All in One SEO、SEOPressがインストールされている場合、Lingua Forgeはそれらを検出し、重複出力を避けるために適応します。hreflangについては、LFが完全に引き継ぎ、プラグインの出力を抑制します。これらのプラグインは多言語ルーティング設定に正しいhreflangを生成できないためです。Open Graphについては、LFはog:localeとog:locale:alternateのみを追加します — 多言語信号はプラグインが提供できないためです — そして基本のOGセットはプラグインに任せます。Schema.orgについては、LFは競合を避けるために自身の出力を完全に無効にします。','Images'=>'画像','Improve writing'=>'文章を改善','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'ブロックエディタで、ソーシャルアイコンブロックを追加します。各アイコンのリンク設定を開き、以下の"share:"値のいずれかをURLとして入力します。フロントエンドでは、LFが現在のページに適した共有URLに置き換えます。','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'名前、説明、inLanguage、URL、画像、そして価格、通貨、在庫状況を含むOfferを含みます。価格と在庫状況はソース言語の製品（共有在庫モデル）から取得します。','Includes site name, url, and inLanguage.'=>'サイト名、URL、inLanguageを含みます。','Informative'=>'情報提供','Input tokens'=>'入力トークン','Install'=>'インストール','Install a Language'=>'言語をインストール','Installed SEO plugins'=>'インストール済みのSEOプラグイン','Installing…'=>'インストール中…','instock / oos / pending from WC stock status'=>'WCの在庫状況からの在庫あり / 在庫切れ / 保留中','Instructions (optional)'=>'指示（任意）','Instructions / key points'=>'指示 / 重要ポイント','Insufficient permissions.'=>'権限が不十分です。','Integration API'=>'統合API','Internal Link Fixer'=>'内部リンク修正ツール','Introduction only'=>'序文のみ','Invalid API key — double-check the key entered in the AI Provider settings.'=>'無効なAPIキー — AIプロバイダー設定で入力したキーを再確認してください。','Invalid file reference.'=>'無効なファイル参照です。','Invalid filename.'=>'無効なファイル名です。','Invalid language code.'=>'無効な言語コード。','Invalid language.'=>'無効な言語。','Invalid locale code.'=>'無効なロケールコードです。','Invalid or primary language.'=>'無効または主要な言語。','Invalid post ID.'=>'無効な投稿ID。','Invalid post type.'=>'無効な投稿タイプ。','Invalid taxonomy.'=>'無効なタクソノミー。','Invalid template part.'=>'無効なテンプレート部分。','Invalid template type.'=>'無効なテンプレートタイプ。','JavaScript-powered actions'=>'JavaScriptを利用したアクション','Just now'=>'今しがた','Key points, ideas, or structure to build from…'=>'ポイント、アイデア、または構造の構築に役立つもの…','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'キーはAES-256-GCMを使用してサイト固有の秘密（LINGUAFORGE_SECRET）で静止時に暗号化されます。秘密をローテーションせずにデータベースエクスポートを共有しないでください。','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'キーはAES-256-CBCで暗号化され、WordPressデータベースに保存されます。暗号化の秘密はWordPressの認証ソルト（wp-config.php）から導出されるため、平文のキーはデータベースに触れません。','Landing / Short-form'=>'ランディング / ショートフォーム','Language'=>'言語','Language %s installed successfully.'=>'言語 %s が正常にインストールされました。','Language (optional)'=>'言語（任意）','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'このサーバーでは言語のインストールが無効になっています（DISALLOW_FILE_MODSが設定されています）。','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'このサーバーでは言語のインストールが無効になっています。wp-config.phpにDISALLOW_FILE_MODS定数が設定されています。WP-CLIを使って手動で言語パックをインストールしてください：wp language core install de_DE','Language label'=>'言語ラベル','Language Overrides'=>'言語の上書き','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'言語上書き：Lingua Forge UI文字列のカスタム.po/.mo上書きファイルを管理します。これを使用してプラグインファイルを直接編集する代わりに — 上書きはアップデートを超えて保持されます。','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'言語パックのインストールに失敗しました。すでにインストールされているか、ロケールコードが正しくないか、サーバーがファイル書き込みをブロックしている可能性があります。','Language Setup'=>'言語設定','Language Switcher'=>'言語切替器','Language switcher'=>'言語切り替え器','Language uninstalled. %d post deleted.'=>'言語がアンインストールされました。%d件の投稿が削除されました。' . "\0" . '','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'テーマのテンプレートパーツの言語固有のコピー。スキャフォールディング後、テンプレートは言語固有のパーツを参照するように更新されます。','Language:'=>'言語:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'ルーターに現在認識されている言語（インストールされたWordPressロケールパックと主要な言語から派生）。下のセクションで追加の言語パックをインストールして、ルーティングと翻訳に利用できる言語を増やしてください。','Last 30 days'=>'過去30日間','Last 7 days'=>'過去7日間','Last generated: %s'=>'最終生成日時：%s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'最後のルールベースのSEOスコア。設定 → SEO → 分析で更新してください。','Last run: %s ago'=>'最後の実行：%s前','Lead paragraph (≤60 w)'=>'リード段落（≤60語）','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'モデルフィールドを空白のままにすると、その階層の組み込みデフォルトを使用します。プレースホルダーテキストは使用されるモデルを示します。','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'ブランド名や言語に依存しない用語で、どの言語から翻訳しても適用されるべき場合は空白のままにします。','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'すべてのターゲット言語にこのエントリを適用するには空白のままにします。ブランド名や略語、すべての翻訳でそのまま保持すべき用語に最適です。','Leave blank to keep the existing key. Enter a new value to replace it.'=>'既存のキーを維持するには空白のままにします。新しい値を入力して置き換えます。','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'空白のままにしてビルトインのデフォルトを使用します。保存済みの上書きをクリアすると、次回保存時にデフォルトに戻ります。','Legacy lf-social-share mu-plugin'=>'レガシー lf-social-share mu-plugin','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'レガシー lf-social-share mu-pluginが検出されました。LFは基本のOGセットをmu-pluginに委ね、og:locale + og:locale:alternateのみを出力します。mu-pluginを無効にできます — LFの内蔵ソーシャルシェア（SEO → ソーシャルシェアタブ）とOpen Graphは同じ機能をカバーしています。','Legacy post-based (CPT)'=>'レガシー投稿ベース（CPT）','Legal / Compliance'=>'法的 / コンプライアンス','Legal / Compliance instructions'=>'法的 / コンプライアンス指示','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LFは常にog:localeとog:locale:alternateを追加します — 多言語OG信号は一般的なSEOプラグインが正しく生成できないものです。基本のOGセット（og:title、og:description、og:image）は、他のプラグインがない場合に出力します。SEOプラグインがインストールされている場合、重複を避けるために基本セットをスキップします — それはプラグインが"より良い"からではなく、重複が価値を生まないためです。','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LFはすべての翻訳グループのxhtml:link alternatesを含む独自のサイトマップを生成します。SEOプラグインがインストールされている場合、それは別のサイトマップを生成します — 両者は独立して共存します。両方をGoogle Search Consoleに送信してください：SEOプラグインのサイトマップはコンテンツの発見用、LFのサイトマップは言語関係の信号用です。','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LFはhreflangタグを出力し、多言語ページからWordPressコアのcanonicalタグを削除しました。','LF is suppressing hreflang output from: %s'=>'LFは次のものからhreflang出力を抑制しています：%s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LFは設定されたすべての言語について正確なhreflangを出力します、x-defaultも含めて。一般的なSEOプラグインはLFのルーティング設定にアクセスできず、不正確なURLに基づいてhreflangを生成します。LFはフィルターを通じてこれらの出力を抑制し、衝突を防ぎます。','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LFは言語ルーティング設定に結びついた多言語JSON-LDを出力します。SEOプラグインがインストールされている場合、LFは自身のスキーマ出力を完全に無効にします：重複するJSON-LDグラフは検証エラーを引き起こし、既存のグラフを補足するクリーンな方法はありません。','LF provides'=>'LFは提供します','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LFは、多言語ページでWordPressコアの正規タグを削除します。これは、ルーターの言語プレフィックス付き書き換えルールとhreflang x-defaultが、多言語サイトの正しい正規シグナルであるためです。これにより、SEOプラグインも正規タグを出力している場合の二重正規タグを防ぎます。LFは独自の正規タグを追加しません — 言語ルーティングですでに各URLが正規化されているからです。','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'LF所有のエントリは現在、$wp_rewrite->extra_rules_top に登録されています。404エラーやルーティングの競合を診断するのに役立ちます。バグ報告時にこれらをコピーしてください。','Light'=>'ライト','Light (default — fast and cost-effective)'=>'ライト（デフォルト — 高速かつコスト効率的）','Light (fast and cost-effective — Haiku / Flash)'=>'ライト（高速かつコスト効率的 — Haiku / Flash）','Light model'=>'ライトモデル','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'ライト：メタディスクリプションや抜粋生成に使用 — 高速で低コスト。','Limit results to pages in the given Lingua Forge language code.'=>'指定されたLingua Forgeの言語コードのページに結果を限定します。','Limits'=>'制限','Lingua Forge'=>'リンガフォージ','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forgeは、多言語ルーティング、AI駆動の翻訳、hreflang SEOタグ、言語切り替えをWordPressサイトに追加します。','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forgeは、FacebookやPinterestなどのプラットフォームで商品URLを共有したときに、正しい商品タイプ、価格、在庫状況を表示させるために、WooCommerce専用のOpen Graphプロパティを商品ページに追加します。','Lingua Forge AI Tools'=>'Lingua Forge AIツール','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forgeは、動的な共有URLを備えたWordPressコアのソーシャルアイコンブロックを拡張します。任意のアイコンのリンクを「share:」値に設定すると、LFはレンダリング時にそれを正しい共有URLまたはJavaScriptアクションに書き換えます — カスタムコードやサードパーティプラグインは不要です。','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forgeは、/lf-sitemap.xmlに専用のXMLサイトマップを生成し、すべての翻訳コンテンツの言語代替リンクを追加します。このサイトマップは、WordPressコアのサイトマップやSEOプラグインのサイトマップを補完します — 置き換えるものではありません。','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forgeは、完全な多言語SEOソリューションです。追加のSEOプラグインは必要ありません。','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forgeは、完全な多言語SEOソリューションです。追加のSEOプラグインやサイトマッププラグインは必要ありません。','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forgeは、すべてのページの設定された言語ごとに<link rel="alternate" hreflang>タグを出力し、ソース言語を指すx-defaultも含まれます。これは、Googleや他の検索エンジンにとって主要な多言語SEOシグナルです。追加のSEOプラグインは必要ありません。','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forgeは、Open GraphとTwitter Cardのメタタグを出力し、共有されたURLがソーシャルプラットフォーム上で正しい言語、タイトル、説明、画像を表示するようにします。','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forgeは、Schema.orgのJSON-LD構造化データを出力し、検索エンジンがコンテンツタイプ、言語、メタデータを理解できるようにします。これは、多言語コンテンツの言語注釈をGoogleや他のクローラーに伝える主要な方法です。','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forgeは、言語間で編集動作を一貫させるために、デフォルトで2つのGutenberg機能を制限しています。完全なGutenberg / FSE機能が必要な場合は、ここでオプトインしてください。','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forgeは、二次WP_Queryインスタンス（サイドバウィジェット、テンプレートブロック、プラグインルックアップ）をアクティブな言語に制限するために、_lf_langメタ制約を注入します。ここにリストされた投稿タイプは、その制約から除外されており、クエリは常にフィルタリングされません。','Lingua Forge Settings'=>'Lingua Forge設定','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forgeは、冗長なAI API呼び出しを避けるために2つの独立したキャッシング層を使用します。各層を検査・管理するには、下のタブを使用してください。','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forgeは、冗長なAI API呼び出しを減らすために2つの独立したキャッシング層を使用します：','Lingua Forge uses two model tiers per provider:'=>'Lingua Forgeは、各プロバイダーに対して2つのモデル階層を使用します。','Lingua Forge version'=>'Lingua Forgeバージョン','Lingua Forge — Quick Translate'=>'リンガフォージ — クイック翻訳','Lingua Forge — Settings'=>'Lingua Forge — 設定','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Lingua Forgeの内蔵のソーシャルシェアとOpen Graphモジュールは、mu-pluginが提供するすべての機能をカバーし、多言語のog:localeサポートも含みます。mu-pluginを安全に無効化できます。','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge、WordPress、PHPのバージョン；アクティブなテーマ；URL構造；WPサイトの言語と主要コンテンツの言語。WPサイトの言語の横に赤いインジケーターが表示されている場合、それはアクティブなコンテンツ言語のいずれでもないことを意味します — まず設定→一般で修正してください。','Link copied'=>'リンクがコピーされました','link(s)'=>'リンク','Links'=>'リンク','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'アクティブなサードパーティのSEOプラグインを一覧表示します。これらが存在する場合、Lingua Forgeは出力を適応させます — 機能ごとの詳細については設定→SEO→互換性を参照してください。','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'_lf_langメタ値のない公開済み投稿を持つ投稿タイプを一覧表示します。このタグがない投稿はすべての言語フィルタから見えなくなります。修復ボタンを使用してソース言語のタグ付けを行うか、除外して完全に言語ルーティングから除外してください。','Load available languages'=>'利用可能な言語を読み込む','Load content'=>'コンテンツを読み込む','Loaded from cache.'=>'キャッシュから読み込みました。','Loading…'=>'読み込み中…','Locale only'=>'ロケールのみ','Locked — a conflicting SEO plugin is active. See the notice above.'=>'ロックされています — 競合するSEOプラグインがアクティブです。上記の通知を参照してください。','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translateはカスタム翻訳をwp-content/languages/loco/に保存します。これはWPコアのアップデートやプラグインの再インストール、Loco Translateの削除によって静かに消去される可能性があります。ここにファイルをコピーすると、それらはLingua Forgeのi18n-overridesディレクトリに移動され、これらのイベントを通じて持続し、すべてのリクエストで自動的に読み込まれます。','Loco Translate — Copy to Safe Storage'=>'Loco Translate — セーフストレージにコピー','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI機能をトリガーできる最低のWordPress能力。これを厳しく設定すると、投稿者やトライアルアカウントが有料のAI呼び出しを行うのを防ぎます。個別の機能は、linguaforge_required_capabilityフィルターを通じて上書き可能です。','Maintenance'=>'メンテナンス','Maintenance Tab'=>'メンテナンスタブ','Make casual'=>'カジュアルにする','Make concise'=>'簡潔にする','Make formal'=>'フォーマルにする','Manage your account, review usage, or top up credits:'=>'アカウント管理、使用状況の確認、クレジットのチャージ：','Mark citations needed'=>'引用が必要な箇所にマーク','Max context characters'=>'コンテキストの最大文字数','Max hints characters'=>'ヒントの最大文字数','Max input characters'=>'最大入力文字数','Max output tokens'=>'最大出力トークン数','Maximum characters accepted from the input field. Default: 8 000.'=>'入力フィールドから受け付ける最大文字数。デフォルト：8,000。','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'ヒントが提供されていない場合に、シードコンテキストとしてAIに渡される既存の投稿内容の最大文字数。デフォルト：6,000。','Maximum characters read from the Hints field. Default: 2 000.'=>'ヒントフィールドから読み取る最大文字数。デフォルト：2,000。','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'AIに送信される投稿内容の最大文字数。0は制限なしを意味し、常に全内容が送信されます（推奨）。プロバイダーに厳しいコンテキストウィンドウがある場合のみ非ゼロの値を設定してください。内容が切り詰められるとPHPエラーログに警告が記録されます。','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'AIが単一の翻訳応答で生成できる最大トークン数。翻訳が静かに途中で切れる場合は、この値を増やしてください。デフォルトは16,000です。','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'AIが1回の生成で生成できる最大トークン数。記事全体が切り捨てられる場合はこれを増やしてください。デフォルト：8,192。','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AIが1回のクイック翻訳で生成できる最大トークン数。デフォルト：2,000。','Meta Description'=>'メタディスクリプション','Meta description'=>'メタディスクリプション','Meta Description, Excerpt Generator'=>'メタディスクリプション、抜粋生成','Meta Description, Excerpt Generator, quick translate'=>'メタディスクリプション、抜粋ジェネレーター、クイック翻訳','Metric'=>'メトリック','Minimum role'=>'最低ロール','Missing'=>'欠落','Missing pattern name or language.'=>'パターン名または言語が欠落しています。','Mode'=>'モード','Model'=>'モデル','Model ID'=>'モデルID','Model tier'=>'モデルの階層','Model tiers'=>'モデル階層','Models'=>'モデル','Modified'=>'最終更新日','Most recent cached block'=>'最新のキャッシュされたブロック','Most recent cached response'=>'最新のキャッシュされた応答','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'多言語ルーティング、完全な多言語SEO（hreflang、Open Graph、Schema.org、サイトマップ）、およびWordPress用のAIコンテンツツール。言語検出、URLルーティング、翻訳、コンテンツ生成、完全なSEO層 — 追加のプラグインは不要です。','Multilingual SEO'=>'多言語SEO','Multilingual SEO overview'=>'多言語SEOの概要','My Account'=>'マイアカウント','Name'=>'名前','Name displayed in this language. Leave empty to use the source name.'=>'この言語で表示される名前。空白のままにするとソース名が使用されます。','Navigation'=>'ナビゲーション','Navigation has no content to translate.'=>'ナビゲーションに翻訳する内容がありません。','Navigation not found.'=>'ナビゲーションが見つかりません。','Navigation posts are translated via the Router tab, not this button.'=>'ナビゲーション投稿はルータータブ経由で翻訳され、このボタンではありません。','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'ナビゲーションの翻訳にはアクティブなAIプロバイダーが必要です。APIキーをAPIキータブで設定してください。','Navigations'=>'ナビゲーション','Network error — could not reach the provider: %s'=>'ネットワークエラー — プロバイダーに接続できませんでした：%s','Network error — could not reach the WordPress AJAX endpoint.'=>'ネットワークエラー — WordPressのAJAXエンドポイントに到達できませんでした。','Network error.'=>'ネットワークエラー。','Never run'=>'実行しない','No %s version found in this translation group.'=>'この翻訳グループに %s バージョンが見つかりません。','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'特にアクションは必要ありません。Googleは2024年1月にサイトマップのpingエンドポイントを廃止し、robots.txtのSitemap:ディレクティブを通じてサイトマップを検出します — これはLFですでに設定済みです。次回のクロール時にGoogleが取得します。','No active plugins detected.'=>'アクティブなプラグインが検出されませんでした。','No AI provider configured.'=>'AIプロバイダーが設定されていません。','No AI provider configured. Add an API key in Settings → API Keys.'=>'AIプロバイダーが設定されていません。設定 → APIキーでAPIキーを追加してください。','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'選択した期間 (%s) でのAI使用状況は記録されていません。上の範囲を広げて選択してください。','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'まだAI使用状況は記録されていません。エディターが翻訳、メタ説明の生成、その他のAI機能を使用すると、合計がここに表示されます。','No API key configured for this provider.'=>'このプロバイダーのAPIキーが設定されていません。','No API key configured — enter your key in the AI Provider settings.'=>'APIキーが設定されていません — AIプロバイダー設定でキーを入力してください。','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'内蔵指示はありません — 各AI機能は独自の調整済みデフォルトを使用します。以下のカスタムプロンプト指示フィールドに記入して、サイト全体のルールを追加してください。','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'競合するSEOプラグインは検出されませんでした。Lingua ForgeはすべてのSEO出力を独立して処理しています。','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'クレジットが残っていません — platform.openai.com/account/billingでOpenAIアカウントにチャージしてください。','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'まだカスタムLoco Translateファイルは見つかりません。Loco Translateで翻訳を保存するとここに表示されます。','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'外部OGプラグインは検出されませんでした。LFは完全なOG + Twitter Cardセットを出力しています。','No file was selected.'=>'ファイルが選択されていません。','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'現在のフィルターに一致する用語集のエントリがありません。すべてのエントリを表示するにはフィルターをクリアするか、下に新しいエントリを追加してください。','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'まだ用語集のエントリはありません。下に追加して翻訳の用語を強制適用し始めましょう。','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'H1が見つかりません。通常、投稿タイトルがH1です — テーマがそれを出力しているか確認してください。','No images found in content.'=>'コンテンツに画像が見つかりません。','No internal links found to update.'=>'更新する内部リンクが見つかりません。','No key'=>'キーなし','No language-specific template parts found to map.'=>'マッピングするための言語固有のテンプレート部分が見つかりません。','No LF meta description set — using excerpt/content.'=>'LFのメタディスクリプションが設定されていません — 抜粋/コンテンツを使用しています。','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'LFのリライトルールが見つかりませんでした。予期しない場合はパーマリンクをフラッシュしてください。','No links found.'=>'リンクが見つかりませんでした。','No links found. Internal links improve crawlability and user navigation.'=>'リンクが見つかりません。内部リンクはクロール性とユーザーナビゲーションを向上させます。','No meta description found. Generate one via the AI meta description feature.'=>'メタディスクリプションが見つかりません。AIのメタディスクリプション機能を使って生成してください。','No navigation references needed updating.'=>'更新が必要なナビゲーション参照はありません。','No override files uploaded yet.'=>'まだアップロードされた上書きファイルはありません。','No PHP limit'=>'PHP制限なし','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'物理的なrobots.txtファイルが見つかりません。WordPressは仮想的に生成しており、LFのサイトマップディレクティブは自動的に含まれています。','No published posts found for the selected filters.'=>'選択したフィルターに一致する公開済みの投稿が見つかりません。','No response from AI provider. Check your API key and try again.'=>'AIプロバイダーからの応答がありません。APIキーを確認して再試行してください。','No response from provider — check the error log for details.'=>'プロバイダーからの応答がありません — 詳細はエラーログを確認してください。','No secondary languages configured.'=>'セカンダリー言語が設定されていません。','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'二次言語が設定されていません。上の言語パックをインストールしてテンプレートのスキャフォールディングを有効にしてください。','No source content found to translate.'=>'翻訳するためのソースコンテンツが見つかりません。','No source page linked yet.'=>'まだソースページがリンクされていません。','No template part references needed updating.'=>'更新が必要なテンプレート部分の参照はありません。','No terms found.'=>'該当する用語がありません。','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'サードパーティのSEOプラグインは検出されませんでした。Lingua Forgeはすべての多言語SEO出力を処理します。','No title set.'=>'タイトルが設定されていません。','No translated content found. The sitemap will populate once posts have been translated.'=>'翻訳されたコンテンツが見つかりません。投稿が翻訳されるとサイトマップに反映されます。','No translation found — analyzed the source language version.'=>'翻訳が見つかりません — ソース言語バージョンを分析しました。','No {lang} translation registered (TRID missing)'=>'{lang}の翻訳が登録されていません（TRIDが欠落しています）','No — WooCommerce integration class not loaded'=>'— WooCommerce統合クラスが読み込まれていません','not a content language — see notice above'=>'コンテンツ言語ではありません — 上記の通知を参照してください','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'まだ生成されていません。サイトマップは最初の訪問時に作成され、24時間キャッシュされます。','Notes'=>'ノート','Nothing — all types disabled'=>'何もありません — すべてのタイプが無効です','Notice message'=>'通知メッセージ','Notice settings'=>'通知設定','Notify search engines'=>'検索エンジンに通知','Numeric permalink structure is not supported.'=>'数字のパーマリンク構造はサポートされていません。','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Cardタグ：LFのOpen Graphモジュール（SEO → Open Graph & Twitter Cards）で処理されます','Oldest cached block'=>'最も古いキャッシュされたブロック','Oldest cached response'=>'最も古いキャッシュされた応答','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'上記のすべてのセクションをカバーするプレーンテキストのシステムサマリーのワンクリックコピー。これをGitHubのイシューやサポートリクエストに貼り付けると、環境全体が一目でわかります。','Only .mo files are accepted.'=>'.moファイルのみが受け付けられます。','Open an issue →'=>'イシューを開く →','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph & Twitterカード','Open Graph output'=>'Open Graph出力','Open Graph settings saved.'=>'Open Graph設定が保存されました。','Open Search Console →'=>'Open Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'ブラウザのネイティブWeb Shareシート（iOS、Android、一部のデスクトップ）を開きます。サポートされていない場合はクリップボードにコピーします。','OpenAI (GPT)'=>'OpenAI（GPT）','OpenAI Platform'=>'OpenAIプラットフォーム','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'編集者向けの任意のコンテキスト（例："ASIC = Application-Specific Integrated Circuit; 技術的文脈では英語のまま保持"）。','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'オプションです。Bingはすでにrobots.txtのSitemap:ディレクティブを読んでいます — これは次のスケジュールされたチェックを待たずに即座に再クロールをトリガーします。','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'オプションです。Yandexはすでにrobots.txtのSitemap:ディレクティブを読んでいます — これは次のスケジュールされたチェックを待たずに即座に再クロールをトリガーします。','Order storage'=>'注文ストレージ','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'wp_postsの注文 — LFルーティングからshop_orderを除外してください。','Output'=>'出力','Output Article or WebPage schema on singular posts and pages'=>'シングル投稿やページにArticleまたはWebPageスキーマを出力します','Output hreflang tags in wp_head'=>'wp_headにhreflangタグを出力します','Output mode'=>'出力モード','Output Open Graph tags in wp_head'=>'wp_headにOpen Graphタグを出力します','Output Product schema on WooCommerce product pages'=>'WooCommerce商品ページにProductスキーマを出力します','Output Schema.org JSON-LD in wp_head'=>'wp_headにSchema.org JSON-LDを出力します','Output tokens'=>'出力トークン','Output WebSite schema on the front page and blog index'=>'トップページとブログインデックスにWebSiteスキーマを出力します','Overall SEO score'=>'全体的なSEOスコア','overridden'=>'上書き済み','Override file deleted.'=>'上書きファイルが削除されました。','Override file uploaded successfully.'=>'上書きファイルのアップロードに成功しました。','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'このページの翻訳とコンテンツ生成のためのAIプリセットを上書きします。他の機能は常にグローバルプリセットを使用します。','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'このページの翻訳とコンテンツ生成のためのAIプリセットを上書きします。サイト全体のカスタムプロンプト指示（設定 → 動作）は、この選択に関係なく常に各リクエストに追加されます。','Overview'=>'概要','Page'=>'ページ','Part'=>'パーツ','Paste a footnote, sentence, or any snippet here…'=>'フットノート、文章、または任意のスニペットをここに貼り付けてください…','Paste text, or select text in the editor first…'=>'テキストを貼り付けるか、まずエディタでテキストを選択してください…','Paste text, or select text on the page first…'=>'まずテキストを貼り付けるか、ページ上でテキストを選択してください…','Paste your API key…'=>'APIキーを貼り付けてください…','Path prefix (/de/)'=>'パスプレフィックス (/de/)','Path prefix — example.com/de/'=>'パスプレフィックス — example.com/de/','Path routing requires a post-name based permalink structure. Change it in'=>'パスルーティングには投稿名ベースのパーマリンク構造が必要です。これを変更してください','Pattern'=>'パターン','Pattern has no content to translate.'=>'翻訳する内容のないパターンです。','Pattern not found.'=>'パターンが見つかりません。','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'パターンが翻訳され保存されました。コンテンツをブロックエディタのパターン挿入ツールを通じてCPT投稿にコピーするか、再利用可能ブロックの出発点として使用してください。','Pattern translation failed.'=>'パターンの翻訳に失敗しました。','Payment required — your account has no remaining credits.'=>'支払いが必要です — アカウントの残高がありません。','Per-Post Analysis'=>'投稿ごとの分析','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'AI生成の翻訳、メタ記述、抜粋、コンテンツのための投稿ごとのキャッシュ。コンテンツやAI提供者/モデルが変更されると自動的に無効になります。','Permalink rules flushed successfully.'=>'パーマリンクルールが正常にフラッシュされました。','Permalink Structure'=>'パーマリンク構造','Permalink structure is compatible with Lingua Forge path routing.'=>'パーマリンク構造はLingua Forgeのパスルーティングと互換性があります。','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'この言語に関連付けられたすべてのテンプレート、テンプレート部分、パターン、ナビゲーションメニュー、投稿、ページ、カスタム投稿タイプ、商品、および商品バリエーションを永久に削除します。また、この言語がルーターに表示されなくなるようにWordPressのロケールパックファイルも削除します。この操作は取り消せません。','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'本当に %s をアンインストールしますか？これにより、この言語のすべての翻訳コンテンツが削除され、元に戻すことはできません。','Permission denied.'=>'アクセス拒否されました。','Persuasive'=>'説得力','PHP constant'=>'PHP定数','PHP max_execution_time'=>'PHPの最大実行時間','PHP memory_limit'=>'PHPのメモリ制限','PHP version'=>'PHPのバージョン','Pin on Pinterest'=>'Pinterestにピン留め','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'翻訳してはいけない用語や特定の方法で常にレンダリングされる必要がある用語（例：ブランド名、商品名、頭字語）をピン留めします。用語集の制約は、すべてのAI翻訳リクエスト（投稿翻訳、メタディスクリプション、抜粋、FSEテンプレート翻訳）に挿入されます。','Ping Bing'=>'BingにPing','Ping Yandex'=>'YandexにPing','Plain language'=>'平易な言葉','Plain permalinks are not supported.'=>'プレーンパーマリンクはサポートされていません。','Please enter some instructions first…'=>'まずいくつかの指示を入力してください…','Please enter some text first…'=>'まずいくつかのテキストを入力してください…','Plugin'=>'プラグイン','Post'=>'投稿','Post not found or not published.'=>'投稿が見つからないか、公開されていません。','Post not found.'=>'投稿が見つかりません。','Post on X / Twitter'=>'X / Twitterに投稿','Post type'=>'投稿タイプ','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'カンマまたは改行で区切られた投稿タイプのスラッグ。保存時に即座に変更が反映されます — パーマリンクのフラッシュは不要です。','Post Types'=>'投稿タイプ','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'_lf_langを持たない投稿は、すべてのLingua Forge言語フィルターから見えません。これは、コンテンツがインポートされたり、プラグインが有効になる前に作成された場合に起こることがあります。','Prefilled from excerpt. Edit to override.'=>'抜粋から事前入力されています。上書きするには編集してください。','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'価格と在庫状況は常にソース言語の製品を反映しています（共有在庫モデル）。タグは、LFのOpen Graphモジュールが「Full」または「Auto」モードに設定されており、競合するSEOプラグインが検出されない場合にのみ出力されます。','Primary content language'=>'主要コンテンツの言語','Primary Language'=>'プライマリ言語','Primary language'=>'プライマリ言語','Primary language saved.'=>'プライマリ言語が保存されました。','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'主要言語：既存コンテンツが書かれている言語です。すべての翻訳はこの言語から生成されます。これを変更しても投稿は移動・削除されません。','Processing…'=>'処理中…','Product'=>'商品','Product / eCommerce'=>'商品 / eコマース','Product Open Graph'=>'商品Open Graph','Product — WooCommerce product pages'=>'商品 — WooCommerce商品ページ','Profile'=>'プロフィール','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'プロファイルは分析されるコンテンツの種類に応じて閾値と重みを調整します。プロファイルは自動的に解決されますが、分析実行ごとにプロファイルドロップダウンから上書きできます。','Provider'=>'プロバイダー','Provider error (HTTP %1$d): %2$s'=>'プロバイダーエラー（HTTP %1$d）：%2$s','Provider returned no response. Check the WordPress error log for details.'=>'プロバイダーから応答がありません。詳細についてはWordPressのエラーログを確認してください。','Provider service temporarily unavailable — try again in a moment.'=>'プロバイダーサービスは一時的に利用できません — しばらくしてから再試行してください。','Quality'=>'品質','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'品質（デフォルト — Sonnet / GPT-4o / Gemini Pro）','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'品質（ソネット / GPT-4o / ジェミニ Pro）','Quality model'=>'品質モデル','Quality: used for post translation and content generation — higher quality, higher cost.'=>'品質：投稿翻訳やコンテンツ生成に使用 — 高品質でコストも高くなります。','Query Filter Exclusions'=>'クエリフィルター除外','Quick Translate'=>'クイック翻訳','Quick Translation'=>'クイック翻訳','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'スニペット/チャンクモードに使用されるクイック翻訳 — ツールバー、エディター、ブロックポップオーバーから短い文章をオンデマンドで翻訳します。フルページ翻訳とは異なる軽量な設定を使用し、応答を高速かつコスト効率的に保ちます。','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'レート制限 — プロバイダーに送信されたリクエストが多すぎます。少し待ってから再試行してください。','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'GutenbergのcanLockBlocksを再有効化します。特定のブロックの移動や削除を防止する必要がある編集テンプレートに便利です。','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateModeを再有効化します。投稿レベルのテンプレート上書きが意図的なフルサイト編集ワークフローの核心です。','Re-generates and updates the cached result.'=>'キャッシュされた結果を再生成して更新します。','Re-scan'=>'再スキャン','Re-scanning…'=>'再スキャン中…','Re-translate'=>'再翻訳','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'現在のインストールの読み取り専用診断。設定は変更されません — 設定の検証、問題の発見、バグレポートのための情報収集に使用してください。','Reading time'=>'読了時間','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'ブラウザのAccept-Languageヘッダーに基づいて、訪問者を好みの言語にリダイレクトします','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'さらに洗練 — 例：「短くする」や「フォーマルなトーンを使う」…','Refine further:'=>'さらに改善：','Refinement'=>'改善（%d回目）','Refinement failed — please try again.'=>'改善に失敗しました — もう一度お試しください。','Refining…'=>'改善中…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'URLのプレフィックス、言語固有のスラッグ、アーカイブの書き換えを同期させるために、WordPressの書き換えルールを再生成します。主要な言語を変更したり、新しい言語サポートを追加した後に必要です。','Remove stored key'=>'保存されたキーを削除','Repair failed.'=>'修復に失敗しました。','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'上記のルーティング可能な投稿に _lf_lang = %s を付与してタグを修復します。ルーティング除外された投稿タイプの投稿には触れません。これはコンテンツをインポートした後や初期有効化時にのみ実行してください — 一括言語再割り当てツールとしては使用しないでください。','Repair Template Metadata'=>'テンプレートメタデータの修復','Repair template metadata'=>'テンプレートメタデータの修復','Repair — assign _lf_lang = %s to all routable posts above'=>'修復 — 上記のルーティング可能な投稿すべてに _lf_lang = %s を割り当てる','Repairing…'=>'修復中…','Report an issue on GitHub'=>'GitHubで問題を報告','Request failed — please try again.'=>'リクエストに失敗しました — もう一度お試しください。','Request failed.'=>'リクエストに失敗しました。','Request failed. Check your connection.'=>'リクエストに失敗しました。接続を確認してください。','Request failed. Please try again.'=>'リクエストに失敗しました。もう一度お試しください。','Requests'=>'リクエスト','requests / day'=>'リクエスト / 日','Reset'=>'リセット','Result will appear here…'=>'結果はここに表示されます…','Retranslate'=>'再翻訳','Retranslating…'=>'再翻訳中…','Review carefully — links and slugs not updated.'=>'注意深く確認してください — リンクとスラッグが更新されていません。','Review translation before applying'=>'適用前に翻訳を確認してください','Revise'=>'改訂','Revision'=>'改訂','Revision Type'=>'改訂タイプ','Rewrite Rules'=>'書き換えルール','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txtがサイトマップディレクティブとともに更新されました。','Router'=>'ルーター','Router Tab'=>'ルータータブ','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'すべての公開投稿に対して、1つまたはすべてのアクティブな言語のSEO監査を実行します。スコアは投稿ごとに保存され、投稿リストの言語バッジに反映されます。','Run AI Analysis'=>'AI分析を実行','Save'=>'保存','Save analysis settings'=>'分析設定を保存','Save Debug Setting'=>'デバッグ設定を保存','Save Hreflang Settings'=>'Hreflang設定を保存','Save Open Graph Settings'=>'Open Graph設定を保存','Save Router Settings'=>'ルーター設定を保存','Save Schema.org Settings'=>'Schema.org設定を保存','Save Settings'=>'設定を保存','Save Sitemap Settings'=>'サイトマップ設定を保存','Save Social Share Settings'=>'ソーシャルシェア設定を保存','Save the post to persist changes.'=>'変更を保存して投稿を確定します。','Save Uninstall Setting'=>'アンインストール設定を保存','Save WooCommerce SEO Settings'=>'WooCommerce SEO設定を保存','Saved to the meta description field when you apply.'=>'適用時にメタディスクリプション欄に保存されます。','Scan failed: '=>'スキャン失敗: ','Scan request failed. Please try again.'=>'スキャンリクエストに失敗しました。もう一度お試しください。','Scanning posts for broken language links…'=>'壊れた言語リンクをスキャンしています…','Schema output deferred.'=>'Schemaの出力が遅延されました。','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Schema.org出力','Schema.org settings saved.'=>'Schema.org設定が保存されました。','Score'=>'スコア','Score computation'=>'スコア計算','Score history and badges'=>'スコア履歴とバッジ','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'スコアは信号であり判決ではありません。一部のコンテンツは構造的に制限されています — 非常に短いページ、本文が少ないランディングページ、または情報よりもナビゲーションを目的としたページは、自然にスコアが低くなることがあります。この概要を使って、言語間の本物のパリティギャップを見つけてください。','Search'=>'検索','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Search Consoleはインデックス作成とカバレッジエラーの監視に役立ちますが、発見には必須ではありません。','Search Results'=>'検索結果','Sections'=>'セクション','Security check failed — file path is not permitted.'=>'セキュリティチェックに失敗しました。ファイルパスが許可されていません。','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'完全な機能ごとの動作表については、設定 → SEO → 互換性を参照してください。','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'管理する言語を選択して、そのFSEテンプレート、テンプレートパーツ、ナビゲーションメニューを設定します。','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'投稿を選択し、詳細なSEO監査を実行して、その特定の項目の結果とスコアを確認します。','Select language'=>'言語を選択','Send via Telegram'=>'Telegram経由で送信','Send via WhatsApp'=>'WhatsApp経由で送信','SEO'=>'SEO','SEO Analysis'=>'SEO分析','SEO character-count info'=>'SEO文字数情報','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEOプラグインが検出されました：%s。LFはog:localeとog:locale:alternateのみを出力しています。検出されたプラグインは完全なOGセットを処理します。','SEO Plugins'=>'SEOプラグイン','SEO plugins and conflict avoidance:'=>'SEOプラグインと競合回避：','SEO Score System'=>'SEOスコアシステム','SEO Scores'=>'SEOスコア','SEO Tab'=>'SEOタブ','Server setup (subdomain)'=>'サーバー設定（サブドメイン）','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'サイト全体のすべての機能のデフォルトAI動作を設定します。個別の投稿は、Lingua Forgeのメタボックスを通じて翻訳とコンテンツ生成に対してこれを上書きできます。','Settings'=>'設定','Settings saved.'=>'設定が保存されました。','Settings → General → Site Language'=>'設定→一般→サイト言語','Settings → Permalinks'=>'設定 → パーマリンク','Share on Facebook'=>'Facebookで共有','Share on LinkedIn'=>'LinkedInで共有','Share on Mastodon'=>'Mastodonで共有','Share via email (mailto:)'=>'メール（mailto:）で共有','Shared / compatibility mode'=>'共有 / 互換モード','Shop'=>'ショップ','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'短いコンテンツ（3段落以下）は、プロファイルに関係なくサブヘッディングの欠如で罰せられることはありません。簡潔なページは強制的な見出し構造の恩恵を受けません。','Show home link'=>'ホームリンクを表示','Shown when no translation exists for the visitor\'s language.'=>'訪問者の言語に翻訳が存在しない場合に表示される。','Single'=>'シングル','Single %s'=>'シングル %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'単語タイトル (%d 文字) — 2語目を追加すると明確さとキーワードのカバレッジが向上します。','Single: %s'=>'シングル：%s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC日ごとのAIリクエストのサイト全体の上限（ツールバーの翻訳とブロックの改訂の両方をカウント）。カウンターはUTCの真夜中にリセットされます。無効にするには0に設定します。','Sitemap'=>'サイトマップ','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'サイトマップのキャッシュがクリアされました。次回サイトマップURLにアクセスすると再生成されます。','Sitemap output'=>'サイトマップ出力','Sitemap settings saved.'=>'サイトマップ設定が保存されました。','Sitemap URL'=>'サイトマップURL','Size'=>'サイズ','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'ソーシャルアイコンブロック共有：URL：LFの内蔵ソーシャルシェア（SEO → ソーシャルシェア）で処理されます','Social Share'=>'ソーシャルシェア','Social Share settings saved.'=>'ソーシャルシェア設定が保存されました。','Some link fixes failed.'=>'一部のリンク修正に失敗しました。','Some nav ref fixes failed.'=>'一部のナビゲーション参照修正に失敗しました。','Some part fixes failed.'=>'一部のパーツ修正に失敗しました。','Some parts could not be created.'=>'一部のパーツを作成できませんでした。','Some templates could not be created.'=>'一部のテンプレートを作成できませんでした。','Some translations failed.'=>'いくつかの翻訳に失敗しました。','source'=>'ソース','Source file not found.'=>'ソースファイルが見つかりません。','Source lang'=>'ソース言語','Source language'=>'ソース言語','Source term'=>'ソース用語','Source title'=>'ソースタイトル','Standard'=>'標準','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'標準は各機能の調整された温度を使用します：翻訳はT=0.2（正確）、クイック翻訳はT=0.4、コンテンツ生成はT=0.6（創造的）。他のプリセットはすべての機能に単一の固定温度を適用します。','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'モデルの提案を見るには任意のフィールドに入力を開始するか、下のリファレンステーブルを使用してください。ライトおよびミッドティアの品質モデル（俳句、GPT-4oミニ、ジェミニフラッシュ）は翻訳とコンテンツ生成に十分です — フラッグシップの "max" モデルはコストを増加させるだけで、構造化されたテキストの品質向上は最小限です。','Status'=>'ステータス','Status / Actions'=>'ステータス / アクション','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'コンテンツハッシュ、言語ペア、プロバイダー、モデル、プリセットをキーとする生のAI応答を保存します。ソース投稿の内容が変更されるとキャッシュエントリは自動的に無効になります。個別の投稿エントリやこのタブからキャッシュ全体をクリアしてください。','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'コンテンツハッシュごとに完全な翻訳済み投稿出力を保存します。オプトイン（動作で有効）。変更されていないコンテンツの繰り返し翻訳を高速化します。内容が変更されていても新しいAI処理を強制したい場合は、ここでクリアしてください。','Storytelling'=>'ストーリーテリング','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'法的、規制、医療、または技術的なコンテンツのための厳格な保存モード。有効にすると、すべてのAI機能は低サンプリング温度を使用し、以下の付録をシステムプロンプトに付加します。用語、記事番号、単位、ブランド名、規制言語はそのまま保存され、言い換えられません。','Structured Outline'=>'構造化アウトライン','Subdomain (de.example.com)'=>'サブドメイン (de.example.com)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'サブドメインモードでは、すべての言語サブドメイン（例：de.example.com）をこのWordPressインストールにポイントさせる必要があります。モードを切り替えた後は、パーマリンクルールをフラッシュし、キャッシュをクリアしてください。ホームURLにwwwが含まれている場合（例：www.example.com）、lf_base_domainフィルターを使ってベアのエイペックスドメインを設定し、サブドメインが正しく構築されるようにしてください。','Subdomain — de.example.com/'=>'サブドメイン — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'このURLをGoogle Search Consoleにメインのサイトマップとともに送信してください。','Submit to Reddit'=>'Redditに提出','Suggested meta description'=>'提案されたメタディスクリプション','Suggested title'=>'提案されたタイトル','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'サポートされているプロバイダー：Anthropic（Claude）、OpenAI（GPT）、Google（Gemini）。ドロップダウンからアクティブなプロバイダーを選択してください — 一度に1つのプロバイダーのみ使用されます。そのプロバイダーのAPIキーを入力してAI機能を有効にします。','Suppressed: %s.'=>'抑制されました：%s。','Switch to a post-name based structure in'=>'に','System'=>'システム','System Tab'=>'システムタブ','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6、機能ごと','Tag'=>'タグ','Tags emitted'=>'発行されたタグ','Target lang'=>'ターゲット言語','Target Language'=>'ターゲット言語','Target language'=>'ターゲット言語','Target term'=>'ターゲット用語','Target: 140–160 chars for optimal SERP display'=>'ターゲット：最適なSERP表示のために140〜160文字','Technical'=>'技術的','Technical / Scientific'=>'技術 / 科学','Technical / Scientific instructions'=>'技術 / 科学的指示','Template "%s" already exists.'=>'テンプレート「%s」は既に存在します。','Template "{expected}" does not exist — create it in the Site Editor first.'=>'テンプレート "{expected}" は存在しません — まずサイトエディタで作成してください。','Template has no content.'=>'テンプレートに内容がありません。','Template mode'=>'テンプレートモード','Template not found or not stored in the database.'=>'テンプレートが見つからないか、データベースに保存されていません。','Template part "%s" already exists.'=>'テンプレート部分「%s」は既に存在します。','Template part has no content.'=>'テンプレート部分に内容がありません。','Template part not found or not stored in the database.'=>'テンプレート部分が見つからないか、データベースに保存されていません。','Template Parts'=>'テンプレートパーツ','Templates'=>'テンプレート','Test connection'=>'接続テスト','Testing…'=>'テスト中…','Text domain / locale'=>'テキストドメイン / ロケール','Text to translate'=>'翻訳するテキスト','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'APIレスポンスキャッシュは、すべてのAIリクエストの生の結果を保存します — 翻訳、メタ記述、抜粋、コンテンツ生成 — 入力のハッシュによってキー付けされます（コンテンツ、言語ペア、提供者、モデル）。プロンプト調整中やすべてのリクエストをAI提供者に届ける必要がある場合は無効にしてください。無効にしてもキャッシュされたエントリは削除されません — 再有効化すると復元されます。','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'日次クォータ（動作→制限で設定）がここで追跡されます。クォータに達すると、その日のAI呼び出しは停止されます。表はクォータの消費量を示します。','The editor did not accept the content — please try again.'=>'エディターが内容を受け入れませんでした — もう一度お試しください。','The following directive is active in your virtual robots.txt:'=>'次のディレクティブがあなたの仮想 robots.txt で有効になっています：','The lf-social-share mu-plugin is active.'=>'lf-social-share mu-plugin が有効です。','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'lf-social-share mu-plugin が有効です。Lingua Forge の組み込みソーシャルシェアは無効です — mu-plugin はシェアURLの書き換えとJSアクションを処理します。','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'ライト層は、上記のモデル表で設定された高速モデルを使用します（デフォルト：俳句 / フラッシュ）。スニペットの全ページモードと同じ翻訳精度が必要な場合は、クオリティに切り替えてください。','The phrase as it appears in the source text.'=>'ソーステキストに表示されるフレーズ。','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'プライマリ言語は常にサイトのルートで提供されます — パスモードではURLプレフィックスなし、サブドメインモードでは言語サブドメインなし。その他の言語は、以下のURL構造設定に応じて、/lang/パスプレフィックス（例：example.com/de/）または言語サブドメイン（例：de.example.com）を使用します。','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'SEO → 互換性タブはライブ検出状況を示し、各機能エリアでLFが何をしているかを正確に説明します。','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'シェアURLは常に現在のページを反映します — 手動でURLを入力する必要はありません。linguaforge_social_share_urlフィルターを使用して、任意のサービスの解決済みURLを上書きできます。','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'サイトマップはrobots.txtで自動的に通知されます。Google、Bing、Yandexなどの主要な検索エンジンはrobots.txtからそれを検出します。手動提出は必要ありません。','The source page has no footnotes.'=>'ソースページにはフットノートがありません。','The upload failed — please try again.'=>'アップロードに失敗しました。もう一度お試しください。','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'使用量表は、AIトークンの消費を機能（翻訳、メタ記述、抜粋、FSEテンプレート、バッチ分析）、プロバイダー、モデルごとに分解して表示します。日付範囲のボタンを使用して、今日、過去7日間、過去30日間、またはすべての期間でフィルタリングします。','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'WordPressコアのサイトマップはすべてのコンテンツURLをリストします。LFのサイトマップは、xhtml:link hreflang代替を通じて言語バージョンの関係を検索エンジンに伝えます。両方をGoogle Search Consoleに提出して完全なカバレッジを得てください。','The WordPress site language (%1$s) is not among the active Lingua Forge content languages (%2$s). This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'WordPressサイトの言語（%1$s）は、アクティブなLingua Forgeコンテンツ言語（%2$s）に含まれていません。これにより、WooCommerceの商品クエリが結果ゼロを返し、商品画像が失敗し、すべての言語フィルタリングされたコンテンツクエリが壊れます。','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'WordPressサイトの言語設定（設定 → 一般 → サイトの言語）は、コンテンツに使用している言語のいずれかに設定する必要があります。主なコンテンツの言語または二次的な言語のいずれかです。サイトにコンテンツのない言語に設定することはできません。','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'これらのフットノートはソースページからのもので、参考のためにここに表示されています。ブロックエディタを使ってこのページに追加してください。','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'このカタログは各Lingua Forgeリリースごとに更新されます。APIキータブで接続をテストすると、プロバイダーからライブモデルリストも取得し、上記の提案を更新します。','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'これはWooCommerceのシステムページ（ショップ、カート、チェックアウトなど）です。その内容はWooCommerceによって管理されており、スコアは構造的な信号のみを反映し、ユーザー編集可能なSEOコンテンツではありません。','This is the source page. Footnotes are edited directly in the block editor.'=>'これはソースページです。フットノートはブロックエディタで直接編集されます。','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'このキーは現在、サーバー %s から提供されており、ここでは削除できません。上に新しいキーを入力して、データベースの値に上書きしてください。','This language is protected and cannot be uninstalled.'=>'この言語は保護されており、アンインストールできません。','This language matches the WordPress instance locale and cannot be uninstalled.'=>'この言語はWordPressインスタンスのロケールと一致しており、アンインストールできません。','Tier'=>'ティア','Tip: to reset a model to the built-in default, clear the field and save.'=>'ヒント：モデルをビルトインのデフォルトにリセットするには、フィールドをクリアして保存してください。','Title'=>'タイトル','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'タイトル15ポイント · メタディスクリプション20ポイント · 単語数15ポイント · 見出し20ポイント · 画像10ポイント · リンク10ポイント。タイトルのSERP制限は60文字、メタは120〜210文字、単語数は300未満で警告、100未満で失敗。H2が必要。内部リンクも必要。','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'タイトルは %1$d 文字です — SERPs で切り詰められる可能性があります（%2$d 文字未満を目指してください）。','Title is only %d chars — aim for at least 10 characters.'=>'タイトルは %d 文字のみです — 最低 10 文字を目指してください。','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'タイトルのスコアリングルール（すべてのプロファイル）：空の場合は失敗；10文字未満は警告；1語のみは警告；プロファイルのSERP制限（ブログは60文字、商品/ランディングは70文字）を超えると警告。少なくとも10文字、2語以上、SERP制限内であればOK。','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'カスタム暗号化シークレット（派生したwp_salt値の代わり）を使用するには、これをwp-config.phpに追加します：','Today'=>'今日','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'トークンの消費量は、機能、プロバイダー、モデルごとに集計されます。すべての成功したAI呼び出しで記録されます。テスト接続のpingは除外され、合計に影響しません。','Token usage'=>'トークン使用量','Tone'=>'トーン','tone'=>'トーン','Tone:'=>'トーン:','Too many AI requests. Please retry in %d seconds.'=>'AIリクエストが多すぎます。%d秒後に再試行してください。','Total'=>'合計','Total tokens'=>'合計トークン','Translate'=>'翻訳','Translate / Revise'=>'翻訳 / 改訂','Translate / Revise block'=>'ブロックの翻訳 / 改訂','Translate all'=>'すべて翻訳','Translate all %s terms (AI)'=>'すべての %s 用語を翻訳（AI）','Translate all categories (AI)'=>'すべてのカテゴリーを翻訳（AI）','Translate all labels (AI)'=>'すべてのラベルを翻訳（AI）','Translate all tags (AI)'=>'すべてのタグを翻訳（AI）','Translate all terms (AI)'=>'すべての用語（AI）を翻訳','Translate chunk'=>'チャンクを翻訳','Translate Content'=>'コンテンツを翻訳','Translate missing'=>'未翻訳を翻訳','Translate page…'=>'ページを翻訳…','Translated content'=>'翻訳された内容','Translated Labels'=>'翻訳済みラベル','Translated Names'=>'翻訳された名前','Translated title'=>'翻訳されたタイトル','Translated to:'=>'翻訳済み：','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'翻訳済み。サイトエディタで確認 — 内部リンク、ナビゲーションURL、テンプレートスラッグは自動的に更新されません。','Translating…'=>'翻訳中…','Translation Caching'=>'翻訳キャッシング','Translation caching'=>'翻訳キャッシュ','Translation failed. Check the browser console.'=>'翻訳に失敗しました。ブラウザのコンソールを確認してください。','Translation found but permalink could not be generated'=>'翻訳は見つかりましたが、パーマリンクを生成できませんでした','Translation Limits'=>'翻訳の制限','Translation Limits & Behavior'=>'翻訳の制限と動作','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'翻訳の制限：どのユーザーロールがAI翻訳をトリガーできるかを制御し、月間トークン予算を設定します。予算を超えると、その月がリセットされるまでAI呼び出しが停止します。','Translation Memory'=>'翻訳メモリ','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'翻訳メモリは、コンテンツハッシュ、言語ペア、プロバイダー、モデルによってAIの結果をキャッシュします。投稿を編集するとキャッシュエントリが無効になり、次の翻訳呼び出しで新しい結果が得られます。','Translation Memory cleared. %d cached block was removed.'=>'翻訳メモリがクリアされました。%d個のキャッシュされたブロックが削除されました。' . "\0" . '','Translation Memory setting saved.'=>'翻訳メモリ設定が保存されました。','Translation workflow'=>'翻訳ワークフロー','Translation, Content Generator'=>'翻訳、コンテンツ生成','Treat H2 as H1 equivalent'=>'H2をH1とみなす','Type'=>'タイプ','Uli Hake'=>'ハケ・ウリ','Unexpected provider error (HTTP %d).'=>'予期しないプロバイダーエラー（HTTP %d）。','Uninstall %s'=>'%sをアンインストール','Uninstall Behaviour'=>'アンインストール動作','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'アンインストール動作：プラグインをプラグイン → インストール済みプラグイン → 削除から削除したときに何が削除されるかを制御します。プラグインの設定とAIキャッシュは常に削除されます。言語割り当て、翻訳関係、メタ記述、用語集、翻訳メモリはデフォルトで保持されるため、誤ってアンインストールまたは再インストールした場合でも続きから再開できます。「アンインストール時にコンテンツデータを削除する」を有効にするのは、サイトから多言語サポートを完全に削除する場合のみです — これを元に戻すことはできません。','Uninstall setting saved.'=>'アンインストール設定が保存されました。','unknown error'=>'不明なエラー','Unknown provider.'=>'不明なプロバイダー。','Unknown search engine.'=>'不明な検索エンジン。','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'hreflangとは異なり — LFは常に他のプラグインを上書きします。なぜなら、それらはあなたの多言語設定を知ることができないからです — Open Graphは異なります：Yoast、Rank Mathなどのプラグインはすでに正しいOGタグを出力しています。これらを複製しても価値はありません。自動モードでは、LFは有効なSEOプラグインを検出し、彼らが提供できないog:locale（現在の言語）とog:locale:alternate（他の設定された言語）だけを追加します。','Unlimited'=>'無制限','Up'=>'上向き','Upload .mo file'=>'.moファイルをアップロード','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'特定のロケールに対してサードパーティプラグインの文字列を上書きするために、コンパイル済みの.moファイルをアップロードします。例："room"の代わりに"apartment"を使用するカスタムVikBooking翻訳。ファイルはWordPressの命名規則に従う必要があります：{textdomain}-{locale}.mo（例：vikbooking-ca.mo）。これらはアップロードフォルダに保存され、プラグインの更新を超えて保持されます。','Upload Override'=>'上書きアップロード','URL could not be mapped to a post — check the link target exists'=>'URLが投稿にマッピングできませんでした — リンクのターゲットが存在するか確認してください','URL structure'=>'URL構造','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL構造：パスプレフィックスモード（example.com/de/）はサーバーの変更を必要としません。サブドメインモード（de.example.com）はワイルドカードDNSレコード、ワイルドカードSSL証明書、およびWebサーバーの設定変更が必要です — サーバー設定ガイドを参照してください。','URL to enter'=>'入力するURL','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'利用可能な場合はネイティブシェアを使用し、そうでなければクリップボードにコピーします。"シェア"ボタンの推奨デフォルトです。','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'このページの上部のタブを使って各エリアを設定します。ルータータブの変更は即座に反映されます。AIキーとモデル設定の変更は次のAIリクエストに適用されます。','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'言語ペアごとに管理されるユーザー管理の用語表。エントリーは翻訳システムのプロンプトに追加され、AIが好ましい用語を一貫して使用します。ドメイン語彙（"kWp"、"PPA"、"相互接続点"）、翻訳してはいけないブランド名、標準化された規制表現にとって重要です。両方の言語フィールドは任意です："ソース言語"を空白のままにすると、どの言語から翻訳しても適用されます。"ターゲット言語"を空白のままにすると、すべてのターゲット言語に一度に適用されます。','Using custom meta description.'=>'カスタムメタディスクリプションを使用しています。','Using LF AI meta description.'=>'LF AIメタディスクリプションを使用しています。','Value source'=>'値のソース','Version'=>'バージョン','View'=>'表示','View built-in default'=>'ビルトインデフォルトを表示','View current robots.txt'=>'現在のrobots.txtを見る','View details'=>'詳細を見る','View Lingua Forge details'=>'Lingua Forgeの詳細を見る','Visit plugin site'=>'プラグインサイトを訪問','Warning:'=>'警告：','WcPageBridge active'=>'WcPageBridgeが有効','WebSite'=>'Webサイト','WebSite — front page / blog index'=>'Webサイト — フロントページ / ブログインデックス','What LF provides — and collision avoidance'=>'LFが提供するもの — そして衝突回避','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'LFが提供するもの：設定されたすべての言語のhreflangタグ、og:localeとog:locale:alternateを含むOpen GraphとTwitterカードタグ、Schema.org JSON-LDとinLanguageアノテーション、すべての翻訳グループのxhtml:link代替エントリを持つ専用の多言語サイトマップ /lf-sitemap.xml。','When another SEO plugin is installed'=>'他のSEOプラグインがインストールされている場合','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'デバッグログが有効になっている場合（以下のトグルまたはwp-config.phpでLINGUAFORGE_AI_DEBUGを定義）、翻訳とFSEテンプレートの翻訳機能は、トラブルシューティングのために生のAIプロンプトと応答をディスクに書き込みます。このセクションを使用して出力を監視し、必要に応じてクリアしてください。大きなページではファイルがすぐに増えることがあります。出力先ディレクトリはlinguaforge_debug_dirフィルターで設定します。','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'有効にすると、言語クッキーやURLの言語プレフィックスがない初回訪問者は、最も近い一致する言語バージョンにリダイレクトされます。ブラウザの優先言語がアクティブなルーター言語に含まれない場合はリダイレクトはスキップされます。スイッチャーを通じて言語を選択した訪問者は、クッキーが優先され、今後の訪問ではブラウザヘッダーは無視されます。','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'有効にすると、Lingua Forgeは商品ページに次の追加メタタグを出力します：og:type=product、og:price:amount、og:price:currency、og:availability、およびFacebookカタログで使用されるproduct名前空間の同等タグ。','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'有効にすると、サイトマップURLはrobots.txtで自動的に通知され、翻訳されたコンテンツが保存されるとキャッシュが更新されます。','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'ブログプロファイルがH2を必要とし、見つからない場合、分析ツールは最初にH3サブヘッディングを確認し、その後警告を出します。アコーディオンや詳細ブロックのヘッダーはデフォルトでH3です。これらのH3は有効な構造として受け入れられ、OKの結果をもたらし、警告は出ません。','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'WPサイトの言語がコンテンツ言語でない場合：WooCommerceの商品クエリはすべてのカタログブロックで結果がゼロになります；商品画像の委任に失敗します；すべての言語フィルター付きコンテンツクエリが壊れます；言語切替器に誤った非コンテンツ言語のオプションが表示されることがあります。ルーターまたはシステムタブの上部に赤い設定アラートが表示された場合は、まずサイトの言語を修正してください。','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Yoast SEO、Rank Math、All in One SEO、SEOPressがアクティブな場合、Lingua Forgeは自動的にそれらのhreflang出力をフィルター経由で抑制します。一般的なSEOプラグインは単一言語のURL構造に基づいてhreflangを生成し、多言語ルーティング設定を考慮できません。LFの出力は常に正しいです。','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'フルページ翻訳に使用するモデルの階層。品質は上記のModelsテーブルで設定されたモデルを使用し、正確な長文翻訳に推奨されます。速度やコストを優先し、内容が短い場合のみライトに切り替えます。','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'有効な間、mu-pluginは基本的なOGセットを処理し、LFはロケールタグのみを出力します（自動モード）。これを削除すると、LFは自動的に完全なOGモードに切り替わります。','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerceは有効ではありません。','WooCommerce page translations'=>'WooCommerceページの翻訳','WooCommerce product price'=>'WooCommerce商品価格','WooCommerce SEO settings saved.'=>'WooCommerce SEO設定が保存されました。','WooCommerce store currency'=>'WooCommerceストア通貨','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'WooCommerceのシステムページ（ショップ、カート、チェックアウト、マイアカウント）は除外されます — これらの内容はWooCommerceによって管理されており、SEO編集によって改善できません。','WooCommerce version'=>'WooCommerceのバージョン','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'WooCommerceのバージョン、注文保存モード（CPT / HPOS / 共有）、および4つの組み込みWCページ（ショップ、カート、チェックアウト、マイアカウント）の各言語ごとの翻訳カバレッジ表。','Word count'=>'文字数','WordPress version'=>'WordPressのバージョン','WP core canonical active (hreflang disabled)'=>'WPコアのcanonicalが有効（hreflang無効）','WP instance language'=>'WPインスタンスの言語','WP site language requirement'=>'WPサイトの言語要件','WP-CLI reference'=>'WP-CLIリファレンス','Write AI prompts and responses to disk for troubleshooting'=>'トラブルシューティングのためにAIのプロンプトと応答をディスクに書き込む','XML Sitemap'=>'XMLサイトマップ','Yes'=>'はい','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'キーを定数や環境変数として定義することもできます（例：wp-config.php）。これらのソースは、データベースキーが保存されていない場合に自動的にフォールバックとして使用されます。','You do not have permission to manage these settings.'=>'これらの設定を管理する権限がありません。','You do not have permission to read this post.'=>'この投稿を読む権限がありません。','{n} stale path(s)'=>'{n} の古いパス','~%d min read'=>'~%d分で読む' . "\0" . '','— AI features are disabled.'=>'— AI機能は無効になっています。','— Any source language —'=>'— いずれかのソース言語 —','— Any target language —'=>'— いずれかのターゲット言語 —','— Any target —'=>'— いずれかのターゲット —','— Any —'=>'— いずれか —','— Auto-detect —'=>'— 自動検出 —','— auto-detect —'=>'— 自動検出 —','— Deferred to plugin'=>'— プラグインに委譲','— Disabled'=>'— 無効','— Not detected'=>'— 検出されませんでした','— select a language —'=>'— 言語を選択 —','← Back'=>'← 戻る','↑ Detected from current post'=>'↑ 現在の投稿から検出','→ Locale tags only (manual setting)'=>'→ ロケールタグのみ（手動設定）','→ Locale tags only — deferring base OG to plugin'=>'→ ロケールタグのみ — 基本OGをプラグインに委譲','↺ Re-translate'=>'↺ 再翻訳','↺ Refine'=>'↺ 改善','↺ Refresh'=>'↺ 更新','↺ Refresh AI Analysis'=>'↺ AI分析を更新','↺ Refreshing…'=>'↺ 更新中…','⚠ Borderline'=>'境界線付近','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ <strong>{lang}</strong>の投稿が見つかりません。すべての翻訳された投稿の言語メタが<strong>{lang}</strong>に設定されていることを確認してください。','⚠ No changes'=>'⚠ 変更なし','⚠ No changes — re-scan?'=>'⚠ 変更なし — 再スキャンしますか？','✅ Fixed ({n})'=>'✅ 修正済み ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong>の壊れたリンクやテンプレートの不一致は見つかりませんでした。<strong>{scanned}</strong>の投稿とページをスキャンし、すべてのチェックに合格しました。ヘッダー、フッター、サイドバーのテンプレート部分のリンクは含まれていません — それらを個別に確認するには「テンプレート部分を修正」ボタンを使用してください。','✅ Template fixed'=>'✅ テンプレートが修正されました','✓ %s notified successfully.'=>'✓ %sが正常に通知されました。','✓ Active'=>'✓ アクティブ','✓ Active at /lf-sitemap.xml'=>'✓ /lf-sitemap.xml でアクティブ','✓ Active — %d URL entry with language alternates'=>'✓ アクティブ — %d URLエントリとその言語の代替' . "\0" . '','✓ Active — full OG + Twitter Cards'=>'✓ アクティブ — 完全なOG + Twitterカード','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ アクティブ — ロケールタグのみ（og:locale、og:locale:alternate）','✓ All parts created.'=>'✓ すべてのパーツが作成されました。','✓ All templates created.'=>'✓ すべてのテンプレートが作成されました。','✓ All translated.'=>'✓ すべて翻訳完了。','✓ Configured'=>'✓ 設定済み','✓ Connection OK'=>'✓ 接続OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ コンテンツが生成されました — オーバーレイを見て、レビュー、改善、適用してください。','✓ Done'=>'✓ 完了','✓ Enabled'=>'✓ 有効','✓ Good length'=>'良い長さ','✓ Hreflang active'=>'✓ Hreflangが有効','✓ In safe storage'=>'✓ セーフストレージに保存済み','✓ Language installed.'=>'✓ 言語がインストールされました。','✓ LF outputs'=>'✓ LF出力','✓ LF outputs Article / WebPage / WebSite'=>'✓ LFはArticle / WebPage / WebSiteを出力','✓ LF outputs full OG + Twitter Cards'=>'✓ LFは完全なOG + Twitterカードを出力','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF出力 — プラグインhreflangは抑制されている','✓ Links fixed.'=>'✓ リンクが修正されました。','✓ Nav refs fixed.'=>'✓ ナビゲーション参照が修正されました。','✓ Parts fixed.'=>'✓ パーツが修正されました。','✓ Pattern translated.'=>'✓ パターンが翻訳されました。','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ 物理的なrobots.txtが見つかりました。LFのサイトマップ指示もあります。','✓ Refined — review the updated draft above.'=>'✓ 改善完了 — 上記の更新されたドラフトを確認してください。','✓ Translation saved'=>'✓ 翻訳が保存されました','✓ WP core canonical removed'=>'✓ WPコアのcanonicalが削除されました','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %sのpingに失敗しました。サイトマップURLはrobots.txtでまだ通知されています — 検索エンジンは次のクロール時に検出します。','✗ Disabled'=>'✗ 無効','✗ Error:'=>'✗ エラー:','✗ Failed:'=>'✗ 失敗:','✗ Not configured'=>'✗ 未設定','✗ Too long'=>'長すぎる','✗ Too short'=>'短すぎる','❌ Failed'=>'❌ 失敗','📄 Wrong template'=>'📄 間違ったテンプレート','📍 Stale path (page moved)'=>'📍 古いパス（ページが移動しました）']];
